/* aniseed plants */
const spStarAnise=(x,y,s)=>spG(x,y,s,Array.from({length:8},(_,i)=>`<ellipse cx="0" cy="-8" rx="3.6" ry="8" fill="#7a3f1e" stroke="#4e2610" transform="rotate(${i*45})"/>`).join("")+`<circle r="3" fill="#4e2610"/>`);
const spFennel=(x,y,s)=>spG(x,y,s,`<path d="M0 0V-50" stroke="#7fa83a" stroke-width="2"/>${[-46,-36,-26].map((yy,i)=>`<path d="M0 ${yy}l${i%2?14:-14} -10M0 ${yy}l${i%2?-10:10} -12" stroke="#9cc65a" stroke-width="1"/>`).join("")}<path d="M-14 -52Q0 -66 14 -52" stroke="#d9c43a" stroke-width="2" fill="none"/>${[-12,-6,0,6,12].map(a=>`<circle cx="${a}" cy="${-56-Math.abs(a)*-.2}" r="2" fill="#e6d24a"/>`).join("")}`);
const spLiquorice=(x,y)=>[0,1,2].map(i=>`<rect x="${x-14+i*3}" y="${y-4+i*5}" width="30" height="5" rx="2.4" fill="#6b4426" stroke="#3a2214" transform="rotate(${-10+i*8} ${x} ${y})"/>`).join("");
/* glass of aniseed spirit that turns cloudy when water is added */
const spLouche=(x,y,b,s)=>spG(x,y,s,`<path d="M-15 -26H15V-2Q15 0 13 0H-13Q-15 0 -15 -2Z" fill="#e3d36a" opacity=".55"/><path d="M-15 -26H15V-2Q15 0 13 0H-13Q-15 0 -15 -2Z" fill="#f2ead0" opacity="0"><animate attributeName="opacity" from="0" to=".95" begin="${b||1}s" dur="2.2s" fill="freeze"/></path><path d="M-16 -40H16V-2Q16 1 13 1H-13Q-16 1 -16 -2Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/>`);
/* bitter roots and bark */
const spGentian=(x,y)=>`<path d="M${x} ${y}q-6 12 -2 26M${x+4} ${y}q4 14 -4 30M${x-2} ${y+12}l-8 10" stroke="#d9b24a" stroke-width="4" fill="none" stroke-linecap="round"/>`;
const spBark=(x,y)=>`<path d="M${x-16} ${y}Q${x} ${y-10} ${x+16} ${y}Q${x+18} ${y+6} ${x+12} ${y+8}Q${x} ${y-2} ${x-12} ${y+8}Q${x-18} ${y+6} ${x-16} ${y}Z" fill="#8a4a24" stroke="#4e2610"/>`;
const spArtichoke=(x,y,s)=>spG(x,y,s,`<path d="M0 0V14" stroke="#6f8f3a" stroke-width="3"/>${[[0,-8,14],[0,-16,11],[0,-23,7]].map(([a,b,r])=>`<path d="M${-r} ${b}Q0 ${b+10} ${r} ${b}Q0 ${b-8} ${-r} ${b}Z" fill="#7f9e4a" stroke="#4f6e2a"/>`).join("")}`);
/* cherry, nut, cream drop for liqueur families */
const spCherry=(x,y,s)=>spG(x,y,s,`<path d="M0 -10Q4 -26 14 -30M8 -8Q10 -22 14 -30" stroke="#6b4a32" stroke-width="1.6" fill="none"/><circle cx="-2" cy="-4" r="7" fill="#b5153a"/><circle cx="10" cy="-2" r="7" fill="#9a1030"/><circle cx="-4" cy="-6" r="1.8" fill="#ffb0c0"/>`);
const spNut=(x,y,s)=>spG(x,y,s,`<path d="M-10 0Q-12 -18 0 -22Q12 -18 10 0Q0 6 -10 0Z" fill="#b5803e" stroke="#6b4426"/><path d="M0 -20V2" stroke="#6b4426" stroke-width=".8"/><path d="M-11 -12Q0 -20 11 -12" stroke="#6b4426" fill="#8a5a33"/>`);
const spCreamDrop=(x,y,s)=>spG(x,y,s,`<path d="M0 -26Q12 -8 10 0Q8 8 0 8Q-8 8 -10 0Q-12 -8 0 -26Z" fill="#f3e6cf" stroke="#c9b48a"/>`);
/* opaque cream liqueur bottle uses spBottle with beige; gunpowder test for overproof */
const spPowder=(x,y,burn)=>`<g><path d="M${x-22} ${y}Q${x} ${y-16} ${x+22} ${y}Z" fill="#3a3436"/>${burn?`<g opacity="0"><animate attributeName="opacity" from="0" to="1" begin="${burn}s" dur=".4s" fill="freeze"/>${fFire(x,y-4)}</g>`:""}</g>`;
/* mountain range (Alps) */
const spAlps=(x,y,w)=>`<path d="M${x} ${y}L${x+w*.15} ${y-44}L${x+w*.28} ${y-20}L${x+w*.45} ${y-62}L${x+w*.6} ${y-26}L${x+w*.75} ${y-50}L${x+w} ${y}Z" fill="#7d8a96"/><path d="M${x+w*.15} ${y-44}L${x+w*.1} ${y-30}L${x+w*.2} ${y-32}ZM${x+w*.45} ${y-62}L${x+w*.39} ${y-44}L${x+w*.51} ${y-46}ZM${x+w*.75} ${y-50}L${x+w*.7} ${y-36}L${x+w*.8} ${y-38}Z" fill="#fff"/>`;
/* bar counter scene parts */
const spBackBar=(x,y,w)=>`<g><rect x="${x}" y="${y}" width="${w}" height="70" fill="#3b2a26" stroke="#55403a"/>${[0,1].map(r=>`<path d="M${x} ${y+30+r*34}H${x+w}" stroke="#7a5a3c" stroke-width="3"/>`+Array.from({length:Math.floor(w/16)},(_,i)=>`<rect x="${x+5+i*16}" y="${y+12+r*34}" width="8" height="18" rx="2" fill="${["#d9a441","#8c1d40","#9cc65a","#e9dc8c","#c98a3a","#3f7fa8"][(i+r*2)%6]}" opacity=".85"/><rect x="${x+7.5+i*16}" y="${y+7+r*34}" width="3" height="6" fill="#3a2a2f"/>`).join("")).join("")}</g>`;
const spCounter=(x,y,w)=>`<g><rect x="${x}" y="${y}" width="${w}" height="10" rx="2" fill="#8a5a33"/><rect x="${x+4}" y="${y+10}" width="${w-8}" height="40" fill="#4a3324"/></g>`;
const spIceWell=(x,y,w)=>`<g><rect x="${x}" y="${y}" width="${w}" height="26" rx="3" fill="url(#fst)" stroke="#5c646b"/><path d="M${x+w/2} ${y}V${y+26}" stroke="#5c646b"/>${Array.from({length:Math.floor(w/26)},(_,i)=>spIce(x+8+i*12,y+10,.7,i*20)).join("")}${Array.from({length:12},(_,i)=>`<circle cx="${x+w/2+4+(i*7)%(w/2-8)}" cy="${y+6+(i%3)*5}" r="2" fill="#e6f4fb"/>`).join("")}</g>`;
const spSpeedRail=(x,y,n)=>`<g><rect x="${x}" y="${y}" width="${n*18+6}" height="8" rx="2" fill="#5c646b"/>${Array.from({length:n},(_,i)=>spPourer(x+12+i*18,y-28,.5)).join("")}</g>`;
/* step indicator dots for the tasting film */
const spSteps=(x,y,labs,act)=>labs.map((l,i)=>`<circle cx="${x+i*64}" cy="${y}" r="9" fill="${i===act?"#d4a23a":"rgba(255,255,255,.15)"}" stroke="#e8dccf"/>${fT(x+i*64,y+3.5,String(i+1),9,i===act?"#2a1b20":"#fff4dc")}${fT(x+i*64,y+22,l,8.5,i===act?"#f3cd8a":"#e8dccf")}${i<labs.length-1?`<path d="M${x+i*64+11} ${y}H${x+i*64+53}" stroke="#e8dccf" stroke-width="1" stroke-dasharray="3 3"/>`:""}`).join("");
/* named drink with chip height choice (to stagger long names) */
const spDrinkY=(x,cy,name,type,col,o,ings,d)=>fD(d||0,fChip(x,cy,name,"#8c1d40")+spCocktail(x,116,type,col,o)+ings.map((t,i)=>fT(x,136+i*12.5,t,8.6,"#f3cd8a")).join(""));
window.TWG_MEDIA = window.TWG_MEDIA || {};
TWG_MEDIA.films = (TWG_MEDIA.films || []).concat([
/* ===================== s6 Rum ===================== */
{id:"s2_rum", sec:"c", ch:"s6", ic:"maps", t:I3_("Rum e cachaça","Rhum et cachaça","Rum and cachaça"), s:[
 {h:I3_("Canna e succo di canna","Canne et jus de canne","Cane and cane juice"),
  c:I3_("Ogni rum nasce dalla canna da zucchero, una pianta che vive diversi anni nei paesi caldi. Quando i fusti sono maturi si tolgono le foglie e si tagliano rasoterra: le radici restano e la pianta ricaccia. Il mulino schiaccia i fusti e libera un succo dolce che può fermentare subito: questi rum hanno aromi vegetali, erbacei e fruttati pronunciati.",
   "Tout rhum naît de la canne à sucre, une plante qui vit plusieurs années dans les pays chauds. Quand les tiges sont mûres, on retire les feuilles et on coupe au ras du sol : les racines restent et la plante repousse. Le moulin écrase les tiges et libère un jus sucré qui peut fermenter aussitôt : ces rhums ont des arômes végétaux, herbacés et fruités prononcés.",
   "Every rum is born from sugar cane, a plant that lives for several years in hot countries. When the stems are mature, the leaves are stripped and the stems cut close to the ground, so the roots stay and the plant regrows. A mill crushes the stems into a sweet juice that can ferment at once: such rums show pronounced vegetal, grassy and fruity aromas."),
  v:()=>spF(fGround()+spCane(50,170,1)+fD(.5,`<path d="M30 168H70" stroke="#e2622a" stroke-width="2" stroke-dasharray="4 3"/>`+fChip(50,186,w3("taglio rasoterra","coupe au ras du sol","cut near the ground"),"#8c1d40"))
   +fD(1.2,fArrow("M92 100H120")+spRollers(150,90,1.2)+fDrops(150,106,134,"#c8d77a",4)+`<path d="M130 136H170V164Q170 168 166 168H134Q130 168 130 164Z" fill="url(#spgl)" stroke="#e8dccf"/><rect x="132" y="146" width="36" height="20" fill="#c8d77a"/>`)
   +fD(2.2,fArrow("M182 150H204")+fTank(210,100,56,66,{col:"#c8d77a",bub:5})+fChip(250,40,w3("fermenta subito","fermente aussitôt","ferments at once"),"#5e8c31"))
   +fD(3,fChip(250,68,w3("erbaceo, fruttato","herbacé, fruité","grassy, fruity"),"rgba(212,162,58,.85)","#2a1b20")),"summer")},
 {h:I3_("Melassa: qualità e diluizione","Mélasse : qualités et dilution","Molasses: grades and dilution"),
  c:I3_("Quasi tutto il succo va però all'industria dello zucchero: lo si scalda, si formano i cristalli e, raccolto tutto lo zucchero possibile, resta la melassa, densa e appiccicosa. Esistono diverse qualità: quella dei primi passaggi di raffinazione è la migliore, quella delle ultime la più povera. È così concentrata che va diluita con acqua prima di fermentare.",
   "Presque tout le jus part pourtant à l'industrie sucrière : on le chauffe, les cristaux se forment et, une fois récolté tout le sucre possible, il reste la mélasse, épaisse et collante. Il en existe plusieurs qualités : celle des premières étapes du raffinage est la meilleure, celle des dernières la plus pauvre. Elle est si concentrée qu'il faut la diluer à l'eau avant la fermentation.",
   "Most cane juice, however, goes to the sugar industry: it is heated, crystals form and, once as much sugar as possible has been collected, thick, sticky molasses is left. It comes in grades: molasses from the early stages of refining is the best, from the final stages the poorest. It is so concentrated that it must be diluted with water before fermenting."),
  v:()=>spF(fBox(14,24,88,28,w3("succo scaldato","jus chauffé","heated juice"))+fD(.4,fArrow("M106 38H126")+fCrystals(134,42)+fT(148,64,w3("zucchero","sucre","sugar"),9))
   +fD(1,[0,1,2].map(i=>spMolasses(56+i*44,140)+`<rect x="${42+i*44}" y="104" width="28" height="36" fill="#000" opacity="${i*.22}"/>`).join("")+fArrow("M40 158H186")+fT(56,172,w3("inizio","début","early"),9,"#9cc65a")+fT(144,172,w3("fine","fin","late"),9,"#e2622a"))
   +fD(1.8,fChip(100,88,w3("qualità diverse","qualités diverses","different grades"),"#8c1d40"))
   +fD(2.6,spJug(226,150,1,262,120)+fTank(250,96,56,70,{col:"#6b3a1a",bub:4})+fChip(270,186,w3("+ acqua","+ eau","+ water"),"#3f7fa8")))},
 {h:I3_("Fermentazione ed esteri","Fermentation et esters","Fermentation and esters"),
  c:I3_("La fermentazione non fa solo alcol: crea congeneri, e molti produttori cercano di aumentare gli esteri fruttati. La Giamaica spinge questo stile all'estremo: fermentazioni molto aromatiche e alambicco discontinuo danno i rum ad alto tenore di esteri, pungenti e intensamente fruttati. Da soli sarebbero troppo forti, ma in un assemblaggio danno slancio aromatico.",
   "La fermentation ne fait pas que de l'alcool : elle crée des congénères, et beaucoup de producteurs cherchent à augmenter les esters fruités. La Jamaïque pousse ce style à l'extrême : fermentations très aromatiques et alambic à repasse donnent les rhums riches en esters, piquants et intensément fruités. Seuls, ils seraient trop forts, mais dans un assemblage ils apportent un élan aromatique.",
   "Fermentation makes more than alcohol: it creates congeners, and many producers try to boost the fruity esters. Jamaica takes this furthest: highly aromatic fermentations plus pot still distillation give high-ester rums, pungent and intensely fruity. On their own they would be far too powerful, but inside a blend they give an aromatic lift."),
  v:()=>spF(fTank(24,60,84,110,{col:"#a8682e",bub:10})+fD(.3,fYeast(54,128)+fYeast(80,112))+fD(1,spBanana(150,60,1.1)+spPineapple(196,74,1)+fChip(176,30,w3("esteri fruttati","esters fruités","fruity esters"),"#5e8c31"))
   +fD(1.8,spPotStill(146,170,.42)+fChip(176,186,w3("alto tenore di esteri","riche en esters","high-ester"),"#8c1d40"))
   +fD(2.6,fArrow("M232 140H254")+spBottle(282,130,"#c98a3a",{s:.6})+fChip(270,60,w3("slancio al blend","élan au blend","lift for blends"),"rgba(212,162,58,.85)","#2a1b20")+fChip(270,86,w3("Giamaica","Jamaïque","Jamaica"))))},
 {h:I3_("Una regola, marks leggeri","Une règle, marks légers","One rule, light marks"),
  c:I3_("Il rum ha pochissime regole: l'unica vera è che non può diventare uno spirito neutro. Ogni nuovo rum distillato si chiama mark. I marks leggeri escono dalla colonna oltre il 90% circa, con aroma leggero: sono la base di molti rum bianchi e, maturati in rovere, di tanti rum dorati.",
   "Le rhum a très peu de règles : la seule vraie est qu'il ne peut pas devenir un alcool neutre. Chaque rhum tout juste distillé s'appelle un mark. Les marks légers sortent de la colonne à plus de 90 % environ, avec un arôme léger : ils sont la base de nombreux rhums blancs et, vieillis en fût, de beaucoup de rhums dorés.",
   "Rum has very few rules: the only real one is that it cannot become a neutral spirit. Each newly made rum is called a mark. Light marks come off column stills, often above 90% abv, with a light aroma: they are the backbone of many white rums and, once matured in oak, of many golden rums."),
  v:()=>spF(spColumn(60,170,140,10,{steam:false,liq:"#dfe9f0"})+fD(.5,spAbv(130,160,110,92,"abv","#9fd3f0",.5))
   +fD(1.6,fArrow("M150 70H186")+spBottle(214,80,"rgba(230,240,255,.55)",{s:.6})+fChip(214,126,w3("non invecchiato","non vieilli","unaged")))
   +fD(2.4,fArrow("M150 130H186")+fBarrel(214,150,.5)+fArrow("M238 150H256")+spBottle(282,150,"#e8b84a",{s:.55})+fChip(270,186,w3("rum dorati","rhums dorés","golden rums"),"#d4a23a","#2a1b20")))},
 {h:I3_("I marks pesanti","Les marks lourds","Heavy marks"),
  c:I3_("I marks pesanti si distillano a gradazione più bassa, di solito in alambicchi discontinui, spesso pezzi unici. Possono essere molto fruttati o ricchi e sapidi. Alcuni nascono in colonne corte, come molti rum di succo di canna. Dopo un lungo invecchiamento sviluppano frutta matura, banana stramatura e rancio; spesso sono così intensi che servono solo a dare profondità agli assemblaggi.",
   "Les marks lourds sont distillés à plus bas degré, en général en alambics à repasse, souvent des pièces uniques. Ils peuvent être très fruités ou riches et savoureux. Certains naissent en colonnes courtes, comme beaucoup de rhums de jus de canne. Après un long vieillissement, ils développent fruits mûrs, banane blette et rancio ; souvent si intenses qu'ils servent surtout à donner de la profondeur aux assemblages.",
   "Heavy marks are distilled to a lower strength, usually in pot stills, many of them one of a kind. They can be very fruity or rich and savoury. Some come from short columns, like many cane juice rums. After long ageing they develop bruised fruit, over-ripe banana and rancio; many are so intense that blenders use them mainly to add depth."),
  v:()=>spF(spPotStill(34,150,.46)+fD(.4,spAbv(120,160,80,70,"abv","#d4a23a",.4,1))+fChip(70,184,w3("bassa gradazione","bas degré","low strength"),"#8a5a33")
   +fD(1.4,spColumn(170,160,60,3,{steam:false})+fChip(170,184,w3("colonna corta","colonne courte","short column")))
   +fD(2.2,fBarrel(262,120,.6,{cut:1,col:"#7a3a14"})+fClock(262,60,""))
   +fD(3,fChip(262,166,w3("banana, rancio","banane, rancio","banana, rancio"),"rgba(212,162,58,.85)","#2a1b20")))},
 {h:I3_("Assemblaggio e tre ritocchi","Assemblage et trois retouches","Blending and three finishing touches"),
  c:I3_("Il rum è quasi sempre un assemblaggio, anche quando viene da una sola distilleria: lo stile dipende dalla famiglia di marks in maggioranza. Si invecchia più spesso in botti usate che nuove. Poi tre ritocchi: il carbone attivo toglie il colore ma lascia un po' di morbidezza; il caramello aggiunge colore; lo zucchero esalta frutta e rancio, ma in eccesso squilibra.",
   "Le rhum est presque toujours un assemblage, même quand il vient d'une seule distillerie : le style dépend de la famille de marks majoritaire. On vieillit plus souvent en fûts usagés que neufs. Puis trois retouches : le charbon actif retire la couleur mais garde un peu de rondeur ; le caramel ajoute de la couleur ; le sucre flatte fruit et rancio, mais en excès il déséquilibre.",
   "Rum is almost always a blend, even from a single distillery: the style depends on which family of marks makes up the majority. Reused casks are more common than new ones. Then three finishing touches: activated charcoal strips colour but keeps some smoothness; caramel adds colour; sugar flatters fruit and rancio notes, but too much unbalances the rum."),
  v:()=>spF(["#eef3f6","#d9a441","#8a4a1a"].map((c,i)=>fD(i*.3,spBottle(26+i*30,60,c,{s:.48})+spPour(26+i*30,34,112,82,c,2))).join("")+fD(.9,fTank(96,80,54,74,{col:"#b9742e"})+fChip(122,170,w3("assemblaggio","assemblage","blend"),"#8c1d40"))
   +fD(1.7,spCharcoal(188,30,50)+fChip(213,94,w3("carbone attivo","charbon actif","charcoal")))+fD(2.4,spMolasses(270,74)+fChip(270,94,w3("caramello","caramel","caramel")))
   +fD(3.1,spSugar(204,150,2)+fChip(250,180,w3("zucchero, con misura","sucre, avec mesure","sugar, with care"),"#5e8c31")))},
 {h:I3_("Bianco, dorato, scuro","Blanc, doré, brun","White, golden, dark"),
  c:I3_("Le leggi sugli stili sono poche, quindi si parla di colore: pratico, ma da usare con cautela. I bianchi sono incolori, a volte invecchiati e poi filtrati; quasi tutti leggeri. I dorati prendono il colore dal rovere, con un po' di caramello, e sono spesso mediamente dolci. Gli scuri sono due mondi: lunghi invecchiamenti con rancio, oppure, più spesso, molto caramello su rum giovani.",
   "Les lois sur les styles sont rares, alors on parle de couleur : pratique, mais à manier avec prudence. Les blancs sont incolores, parfois vieillis puis filtrés ; presque tous légers. Les dorés tirent leur couleur du chêne, avec un peu de caramel, et sont souvent moyennement sucrés. Les bruns sont deux mondes : longs vieillissements avec du rancio, ou, plus souvent, beaucoup de caramel sur des rhums jeunes.",
   "With few laws on styles, people talk about colour: handy, but to be used with care. White rums are colourless, sometimes aged then filtered, and mostly light. Golden rums take their colour from oak, plus a little caramel, and are often medium sweet. Dark rums are two worlds: long ageing with rancio, or, more often, plenty of caramel on young rums."),
  v:()=>spF(spBottle(50,96,"rgba(230,240,255,.55)",{lab:"WHITE"})+fChip(50,150,w3("bianco","blanc","white"))+fChip(50,176,w3("di solito leggero","souvent léger","mostly light"),"#5c646b")
   +fD(1,spBottle(160,96,"#e0a43a",{lab:"GOLD"})+fChip(160,150,w3("dorato","doré","golden"),"#d4a23a","#2a1b20")+fChip(160,176,w3("rovere + caramello","chêne + caramel","oak + caramel")))
   +fD(2,spBottle(270,96,"#5a2a10",{lab:"DARK"})+fChip(270,150,w3("scuro","brun","dark"),"#8a5a33")+fChip(262,176,w3("rancio o caramello","rancio ou caramel","rancio or caramel"),"#8c1d40")))},
 {h:I3_("La tradizione britannica","La tradition britannique","The British tradition"),
  c:I3_("La Marina britannica ha servito una razione quotidiana di rum fino al 1970, diluita, zuccherata e con lime: serviva un rum di carattere, ricco di marks pesanti. La Giamaica dava marks ad alto tenore di esteri; la Guyana marks ricchi, adatti a invecchiamenti molto lunghi, che danno corpo agli assemblaggi. Le Barbados offrono uno stile più morbido e liscio.",
   "La Marine britannique a servi une ration quotidienne de rhum jusqu'en 1970, diluée, sucrée et avec du citron vert : il fallait un rhum de caractère, riche en marks lourds. La Jamaïque fournissait des marks riches en esters ; le Guyana des marks riches, faits pour de très longs vieillissements, qui donnent du corps aux assemblages. La Barbade offre un style plus souple et soyeux.",
   "The British Navy served a daily rum ration until 1970, diluted, sweetened and mixed with lime: it needed a characterful rum built on heavy marks. Jamaica supplied high-ester marks; Guyana supplied rich marks suited to very long ageing, which give weight and mouthfeel to blends. Barbados offers a softer, smoother style."),
  v:()=>spF(`<path d="M20 70Q60 54 100 70L94 84H26Z" fill="#6b4426"/><path d="M60 70V20" stroke="#6b4426" stroke-width="3"/><path d="M62 24L92 40L62 52Z" fill="#fbf3e2"/>`+fChip(60,104,w3("razione fino al 1970","ration jusqu'en 1970","ration until 1970"),"#3f7fa8")
   +fD(.8,spJug(30,170,0)+spCitrus(70,160,8,LIME)+spSugar(100,170,1)+fT(66,190,w3("acqua, zucchero, lime","eau, sucre, citron","water, sugar, lime"),8.5))
   +[["Jamaica","#5e8c31",w3("fruttato, esteri","fruité, esters","fruity, esters")],["Guyana","#8a5a33",w3("ricco, invecchia","riche, vieillit","rich, long-ageing")],["Barbados","#5c646b",w3("morbido","souple","smooth")]].map(([n,c,l],i)=>fD(1.6+i*.6,spPin(170,52+i*46,c)+fT(212,42+i*46,n,10,"#f3cd8a","start")+fT(212,56+i*46,l,9,"#fff4dc","start"))).join(""))},
 {h:I3_("Stili francese e spagnolo","Styles français et espagnol","French and Spanish styles"),
  c:I3_("Martinica e Guadalupa preferivano lo zucchero di barbabietola francese, così distillavano il succo di canna in colonne corte: bianchi tra i più aromatici, per la miscelazione, dorati secchi o abboccati. Lo stile spagnolo nacque a Cuba con colonne moderne ad alta gradazione e breve affinamento: il bianco più popolare. I dorati spagnoli usano molti marks leggeri, vaniglia e spesso zucchero.",
   "La France préférait son sucre de betterave : en Martinique et en Guadeloupe, on distillait donc le jus de canne en colonnes courtes. Blancs très aromatiques, pour le mélange ; dorés secs ou demi-secs. Le style espagnol est né à Cuba avec des colonnes modernes à haut degré et un bref passage en fût : le blanc le plus populaire. Dorés espagnols : marks légers, vanille, souvent du sucre.",
   "In Martinique and Guadeloupe, France favoured its own beet sugar, so cane juice was distilled in short columns: whites among the most aromatic rums, made for mixing, and dry or off-dry golden rums. The Spanish style began in Cuba, with modern high-strength columns and brief ageing: the most popular white style. Spanish golden rums use many light marks, vanilla and often sugar."),
  v:()=>spF(fChip(80,22,w3("francese","français","French"),"#3f7fa8")+spCane(30,140,.6)+spColumn(80,140,56,3,{steam:false})+spBottle(126,104,"rgba(230,240,255,.55)",{s:.5})+fChip(80,160,"rhum agricole","#5e8c31")+fChip(80,184,w3("secco / abboccato","sec / demi-sec","dry / off-dry"))
   +fD(1.6,fChip(240,22,w3("spagnolo","espagnol","Spanish"),"#d4a23a","#2a1b20")+spColumn(200,140,110,9,{steam:false,liq:"#dfe9f0"})+fBarrel(262,120,.45)+fChip(240,160,w3("liscio, leggero","souple, léger","smooth, light"))+fChip(240,184,"Cuba · Panamá · Guatemala","#8c1d40")))},
 {h:I3_("Etichette: età, cachaça, overproof","Étiquettes : âge, cachaça, overproof","Labels: age, cachaça, overproof"),
  c:I3_("Le età in etichetta variano: il numero può indicare il rum più giovane, il più vecchio o una media. Rhum agricole e cachaça segnalano il succo di canna; il Brasile ne produce più di tutta la vodka del mondo, per lo più non invecchiata e leggermente zuccherata. Overproof indica un grado altissimo: per i marinai inglesi 100 proof era circa il 57%, soglia a cui la polvere bagnata bruciava.",
   "Les âges varient : le chiffre peut désigner le rhum le plus jeune, le plus vieux ou une moyenne. Rhum agricole et cachaça signalent le jus de canne ; le Brésil en produit plus que toute la vodka du monde, surtout non vieillie et légèrement sucrée. Overproof indique un très haut degré : pour les marins anglais, 100 proof valait environ 57 %, seuil où la poudre mouillée brûlait.",
   "Age statements are not uniform: a number may mean the youngest rum, the oldest or an average. Rhum agricole and cachaça signal cane juice; Brazil makes more cachaça than all the world's vodka, mostly unaged and lightly sweetened. Overproof means very high strength: for British sailors, 100 proof was about 57% abv, the point at which gunpowder soaked in rum would still burn."),
  v:()=>spF(spBottle(46,92,"#c98a3a",{lab:"12?"})+fChip(46,146,w3("età: leggi bene","âge : lisez bien","age: read closely"),"#8c1d40")
   +fD(1,spBottle(170,92,"rgba(230,240,255,.55)",{lab:"CACHAÇA"})+fChip(170,146,w3("succo di canna","jus de canne","cane juice"),"#5e8c31")+fChip(170,172,w3("Brasile","Brésil","Brazil")))
   +fD(2,spPowder(250,110,2.8)+spAbv(296,140,90,57,"","#e2622a",2.4)+fChip(262,172,"100 proof ≈ 57%","#d4a23a","#2a1b20")+fChip(262,194,"overproof")))}
]},
/* ===================== s7 Tequila and Mezcal ===================== */
{id:"s2_agave", sec:"c", ch:"s7", ic:"maps", t:I3_("Tequila e Mezcal","Tequila et Mezcal","Tequila and Mezcal"), s:[
 {h:I3_("L'agave e l'inulina","L'agave et l'inuline","Agave and inulin"),
  c:I3_("L'agave è originaria dell'America centrale e ne esistono centinaia di specie. Tutte hanno un cuore duro, da cui partono lunghe foglie spinose e cerose, dove la pianta accumula le riserve sotto forma di inulina. Alcune specie impiegano 15–20 anni a maturare, poi fioriscono una sola volta e muoiono. Si raccoglie poco prima della fioritura: massimo di inulina e aromi più complessi.",
   "L'agave est originaire d'Amérique centrale et il en existe des centaines d'espèces. Toutes ont un cœur dur, d'où partent de longues feuilles piquantes et cireuses, où la plante stocke ses réserves sous forme d'inuline. Certaines espèces mettent 15 à 20 ans à mûrir, puis fleurissent une seule fois et meurent. On récolte juste avant la floraison : maximum d'inuline et arômes les plus complexes.",
   "Agave is native to Central America, with hundreds of species. All have a hard core, from which long, spiky, waxy leaves grow, and there the plant stores its reserves as inulin. Some species take 15 to 20 years to mature, then flower just once and die. Growers harvest just before flowering, when inulin and aroma complexity are at their peak."),
  v:()=>spF(fGround()+spAgave(70,170,1.5)+fD(.6,fCall(70,160,60,30,w3("cuore: inulina","cœur : inuline","core: inulin")))
   +fD(1.4,fClock(160,60,w3("15–20 anni","15–20 ans","15–20 years")))
   +fD(2.2,spAgave(250,170,1)+`<path d="M250 160V30" stroke="#7fa83a" stroke-width="4"/>${[40,52,64].map(y=>`<path d="M250 ${y}l-12 -6M250 ${y}l12 -6" stroke="#7fa83a" stroke-width="2"/><circle cx="238" cy="${y-6}" r="4" fill="#f2d64b"/><circle cx="262" cy="${y-6}" r="4" fill="#f2d64b"/>`).join("")}`+fChip(250,186,w3("fiorisce e muore","fleurit et meurt","flowers, then dies"),"#8c1d40"))
   +fD(3,fChip(160,110,w3("raccogli prima","récolter avant","harvest before"),"#5e8c31")),"summer")},
 {h:I3_("Piña e cottura","Piña et cuisson","The piña and cooking"),
  c:I3_("Alla raccolta la pianta si taglia dalle radici e le foglie si eliminano: resta la piña, che sembra un ananas gigante. L'inulina non fermenta così com'è: serve il calore per trasformarla in zuccheri. Per la Tequila la piña cuoce lentamente al vapore in forni di mattoni; per il Mezcal si arrostisce spesso in fosse. I moderni forni a vapore pressurizzato sono rapidi, ma rischiano di bruciare l'agave.",
   "À la récolte, on coupe racines et feuilles : il reste la piña, sorte d'ananas géant. L'inuline ne fermente pas telle quelle : la chaleur la change en sucres. Pour la Tequila, la piña cuit lentement à la vapeur en four de brique ; pour le Mezcal, on la rôtit souvent en fosse. Les fours à vapeur sous pression vont vite, mais risquent de brûler l'agave.",
   "At harvest the plant is cut from its roots and the leaves trimmed away, leaving the piña, which looks like a giant pineapple. Inulin cannot ferment as it is: heat must turn it into sugars. For Tequila the piña is slowly steamed in brick ovens; for Mezcal it is often roasted in pits. Modern pressurised steam ovens are fast but risk burning the agave."),
  v:()=>spF(spPina(46,96,1.4)+fChip(46,116,"piña","#d4a23a","#2a1b20")+fD(.6,fChip(46,150,w3("inulina → zuccheri","inuline → sucres","inulin → sugars"),"#8c1d40")+fT(46,176,w3("serve calore","il faut chauffer","needs heat"),9))
   +fD(1.2,spOven(160,120,.95)+spVapour(160,58,3,16)+fChip(160,146,w3("forno di mattoni","four en brique","brick oven"))+fT(160,166,"Tequila",10,"#f3cd8a"))
   +fD(2,spPit(270,110,.6,1)+fChip(266,146,w3("fossa","fosse","pit"))+fT(270,166,"Mezcal",10,"#f3cd8a"))
   +fD(2.8,fChip(200,190,w3("vapore a pressione","vapeur sous pression","pressurised steam"),"#5c646b")))},
 {h:I3_("Schiacciare e lavare","Broyer et rincer","Crushing and rinsing"),
  c:I3_("Cotta, la piña si schiaccia per liberare un succo molto dolce, lasciando le fibre che le davano struttura. Il metodo tradizionale usa una grande ruota di pietra; oggi, soprattutto per la Tequila, si usano mulini meccanici. Poi l'agave schiacciata si risciacqua con acqua, per non perdere neanche un po' di zucchero.",
   "Une fois cuite, la piña est broyée pour libérer un jus très sucré, en laissant les fibres qui lui donnaient sa structure. La méthode traditionnelle utilise une grande meule en pierre ; aujourd'hui, surtout pour la Tequila, on emploie des moulins mécaniques. Ensuite, l'agave broyé est rincé à l'eau, pour ne pas perdre la moindre trace de sucre.",
   "Once cooked, the piña is crushed to release a very sweet juice, leaving behind the fibres that gave it structure. The traditional method uses a large stone wheel; today, especially for Tequila, mechanical mills are more common. The crushed agave is then rinsed with water so that every last bit of sugar is extracted."),
  v:()=>spF(spTahona(100,130,1.2)+fChip(100,170,w3("ruota di pietra","meule en pierre","stone wheel"),"#8a5a33")
   +fD(1.4,spRollers(240,70,1.1)+fChip(240,40,w3("mulino meccanico","moulin mécanique","mechanical mill"),"#5c646b"))
   +fD(2.2,spJug(214,150,1,248,130)+fDrops(250,130,160,"#e6d58a",3)+`<rect x="232" y="160" width="40" height="18" rx="3" fill="#e6d58a" opacity=".85"/>`+fChip(256,192,w3("risciacquo","rinçage","rinse"),"#3f7fa8")))},
 {h:I3_("Formulazione e fibre","Formulation et fibres","Formulation and fibres"),
  c:I3_("Preparare il liquido zuccherino da fermentare si chiama formulazione. Qui il produttore di Tequila può aggiungere zuccheri non di agave, fino al 49%: diluiscono il carattere dell'agave. I migliori usano solo zuccheri di agave e mettono anche le fibre della piña nel fermentatore, per intensificare gli aromi.",
   "Préparer le liquide sucré à fermenter s'appelle la formulation. Le producteur de Tequila peut alors ajouter des sucres qui ne viennent pas de l'agave, jusqu'à 49 % : ils diluent le caractère de l'agave. Les meilleurs n'utilisent que des sucres d'agave et mettent aussi les fibres de la piña dans la cuve de fermentation, pour intensifier les arômes.",
   "Making up the sweet liquid for fermentation is called formulation. At this stage a Tequila producer may add non-agave sugars, up to 49% of the total: they dilute the agave character. The best producers use agave sugars only and also put piña fibres into the fermenter to boost the agave aromas."),
  v:()=>spF(fChip(160,22,w3("formulazione","formulation","formulation"),"#8c1d40")+`<rect x="30" y="44" width="60" height="110" rx="4" fill="rgba(255,255,255,.1)" stroke="#e8dccf"/><rect x="32" y="${152-108*.51}" width="56" height="${108*.51}" fill="#7aa79c"/><rect x="32" y="46" width="56" height="${108*.49-2}" fill="#e8c25a" opacity=".8"/>`+fT(60,86,"≤49%",11,"#2a1b20")+fT(60,128,"≥51%",11,"#13302a")+fChip(60,174,w3("altri zuccheri","autres sucres","other sugars"))
   +fD(1.4,fTank(170,60,90,110,{col:"#d9c27a",bub:8})+[0,1,2,3,4,5].map(i=>`<path d="M${182+i*12} ${120+(i%2)*14}l10 -4" stroke="#a88a4a" stroke-width="2.4"/>`).join("")+fYeast(200,150)+fCall(220,128,270,50,w3("fibre di piña","fibres de piña","piña fibres"),2.2))
   +fD(3,fChip(214,192,w3("più agave","plus d'agave","more agave"),"#5e8c31")))},
 {h:I3_("Distillare piano, poco legno","Distiller bas, peu de bois","Low strength, little oak"),
  c:I3_("Si può usare la colonna, ma Tequila e Mezcal di qualità sono distillati due volte in alambicco discontinuo: grandi e moderni per la Tequila, piccoli e spesso artigianali per il Mezcal. Si raccoglie a gradi bassi, a volte sotto il 60%. Poi quasi tutti riposano in recipienti inerti o in grandi tini di rovere: le botti piccole sono rare, perché il legno copre facilmente l'agave.",
   "On peut utiliser la colonne, mais les Tequilas et Mezcals de qualité sont distillés deux fois en alambic à repasse : grands et modernes pour la Tequila, petits et souvent artisanaux pour le Mezcal. On recueille à bas degré, parfois sous 60 %. Ensuite, presque tous reposent en cuves inertes ou en grandes cuves de chêne : les petits fûts sont rares, car le bois masque facilement l'agave.",
   "Columns are allowed, but quality Tequila and Mezcal are double distilled in pot stills: large modern ones for Tequila, small and often home-made ones for Mezcal. The spirit is collected at low strength, sometimes below 60% abv. Most then rest in inert vessels or very large oak vats: small barrels are rare, because oak easily drowns the agave."),
  v:()=>spF(spPotStill(30,140,.5)+fChip(66,30,"×2","#d4a23a","#2a1b20")+fD(.6,spAbv(112,150,90,58,"","#9cc65a",.6))+fChip(80,180,w3("sotto il 60%","sous 60 %","below 60% abv"),"#5e8c31")
   +fD(1.6,spSteel(160,90,44,64)+spVat(214,70,60,84,"#e9dc8c")+fChip(214,180,w3("inerte o grande tino","inerte ou grande cuve","inert or large vat")))
   +fD(2.6,fBarrel(290,50,.42)+spNo(290,50,12)+fT(290,76,w3("botte piccola","petit fût","small cask"),8.5)))},
 {h:I3_("Tequila: agave blu e Jalisco","Tequila : agave bleu et Jalisco","Tequila: blue agave and Jalisco"),
  c:I3_("Tequila e Mezcal sono indicazioni geografiche, un po' come Cognac e Armagnac. La Tequila è l'agave più prodotta, dominata da grandi aziende, e usa una sola varietà, l'agave blu, coltivata in cinque stati messicani; il più importante è Jalisco. Matura in 7–10 anni, e in altitudine dà aromi più fruttati: la varietà non è tutto, contano luogo e scelte di produzione.",
   "Tequila et Mezcal sont des indications géographiques, un peu comme Cognac et Armagnac. La Tequila est l'eau-de-vie d'agave la plus produite, dominée par de grandes entreprises, et n'utilise qu'une variété, l'agave bleu, cultivé dans cinq États mexicains, surtout Jalisco. Il mûrit en 7 à 10 ans et, en altitude, donne des arômes plus fruités : le lieu et les choix de production comptent aussi.",
   "Tequila and Mezcal are geographical indications, a bit like Cognac and Armagnac. Tequila is the largest agave spirit, dominated by big companies, and may use only one variety, blue agave, grown in five Mexican states, above all Jalisco. It matures in 7 to 10 years, and at altitude gives fruitier aromas: place and production choices matter as much as the variety."),
  v:()=>spF(fGround()+spAgave(60,170,1.3)+fChip(60,40,w3("agave blu","agave bleu","blue agave"),"#3f7fa8")+fD(.8,fClock(60,90,w3("7–10 anni","7–10 ans","7–10 years")))
   +fD(1.4,`<path d="M150 150L180 70L200 100L230 50L270 150Z" fill="#8a9a7e" opacity=".8"/>`+spPin(230,60,"#b5334a")+fChip(220,30,w3("5 stati · Jalisco","5 États · Jalisco","5 states · Jalisco"),"#8c1d40"))
   +fD(2.4,fChip(250,120,w3("altitudine: frutto","altitude : fruit","altitude: fruitier"),"#5e8c31")+fChip(220,186,w3("grandi aziende","grandes entreprises","big companies"),"#5c646b")),"summer")},
 {h:I3_("Leggere una Tequila","Lire une étiquette de Tequila","Reading a Tequila label"),
  c:I3_("100% agave significa che tutti gli zuccheri vengono dalla pianta; la sola parola Tequila ne richiede il 51%, e il nome mixto non è un termine d'etichetta. Poi le categorie: Blanco o Silver, senza obbligo di affinamento; Gold, non invecchiata ma colorata e ammorbidita con l'abocado; Reposado, almeno due mesi, di solito in grandi tini; Añejo, un anno in botte; Extra Añejo, tre anni.",
   "100 % agave : tous les sucres viennent de la plante ; le seul mot Tequila en exige 51 %, et mixto n'est pas une mention légale. Puis les catégories : Blanco ou Silver, sans obligation de vieillissement ; Gold, non vieillie mais colorée et adoucie à l'abocado ; Reposado, au moins deux mois, souvent en grandes cuves ; Añejo, un an en fût ; Extra Añejo, trois ans.",
   "100% agave means every sugar came from the plant; the word Tequila alone needs only 51%, and mixto is not a labelling term. Then the categories: Blanco or Silver, no ageing required; Gold, unaged but coloured and softened with abocado; Reposado, at least two months, usually in large vats; Añejo, one year in barrels; Extra Añejo, three years."),
  v:()=>spF(fChip(80,22,"100% agave","#5e8c31")+fChip(230,22,"Tequila = 51%+","#5c646b")
   +[["Blanco","rgba(230,240,255,.55)","—"],["Gold","#e8b84a","abocado"],["Reposado","#efd27a",w3("2 mesi","2 mois","2 months")],["Añejo","#d49a3a",w3("1 anno","1 an","1 year")],["Extra Añejo","#a8682e",w3("3 anni","3 ans","3 years")]].map(([n,c,l],i)=>fD(.6+i*.45,spBottle(32+i*64,100,c,{s:.6})+fT(32+i*64,146,n,9,"#f3cd8a")+fChip(32+i*64,170,l,i===1?"#8c1d40":undefined))).join(""))},
 {h:I3_("Mezcal: Oaxaca e fumo","Mezcal : Oaxaca et fumée","Mezcal: Oaxaca and smoke"),
  c:I3_("In Messico ogni distillato d'agave si chiama mezcal, ma in etichetta Mezcal è un'indicazione geografica, soprattutto Oaxaca. Dominano i piccoli produttori e sono ammesse più specie; la più usata è l'espadín. Nella fossa si accende un fuoco che scalda le pietre, poi le piñas si coprono di terra e cuociono: il vapore non dà aromi, l'arrosto sì. Il fumo è la firma del Mezcal.",
   "Au Mexique, toute eau-de-vie d'agave s'appelle mezcal, mais sur l'étiquette Mezcal est une indication géographique, surtout Oaxaca. Les petits producteurs dominent et plusieurs espèces sont permises ; la plus utilisée est l'espadín. Dans la fosse, un feu chauffe les pierres, puis les piñas sont couvertes de terre et cuisent : la vapeur n'apporte pas d'arôme, le rôtissage si. La fumée est la signature du Mezcal.",
   "In Mexico every agave spirit is loosely called mezcal, but on a label Mezcal is a geographical indication, above all Oaxaca. Small producers dominate and several species are allowed; espadín is the most used. A fire heats the stones of a pit, then the piñas are covered with earth to cook: steaming adds no aroma, roasting does. Smoke is Mezcal's signature."),
  v:()=>spF(spPin(60,70,"#b5334a")+fChip(60,90,"Oaxaca","#8c1d40")+fD(.6,spAgave(60,170,.8)+fChip(60,186,"espadín","#3f7fa8"))
   +fD(1.4,spPit(210,120,1.1,1))+fD(2.4,fChip(210,30,w3("fumo","fumée","smoke"),"#5c646b")+fChip(210,176,w3("terra, vegetale","terre, végétal","earthy, vegetal"),"#5e8c31")),"dusk")},
 {h:I3_("Mezcal, Artesanal, Ancestral","Mezcal, Artesanal, Ancestral","Mezcal, Artisanal, Ancestral"),
  c:I3_("Tre categorie aiutano a riconoscere i metodi tradizionali. Mezcal ammette ogni cottura, anche il vapore a pressione, e ogni alambicco, colonna compresa. Artesanal vuole fosse o forni di mattoni, mulini limitati, fermentazione con fibre in pietra, legno o argilla, e alambicchi a fuoco diretto. Ancestral: solo fossa, niente mulini meccanici, fibre anche in distillazione e alambicchi d'argilla.",
   "Trois catégories aident à reconnaître les méthodes traditionnelles. Mezcal admet toute cuisson, même la vapeur sous pression, et tout alambic, colonne comprise. Artesanal exige fosses ou fours en brique, moulins limités, fermentation avec fibres en pierre, bois ou argile, et alambics à feu direct. Ancestral : fosse seulement, pas de moulin mécanique, fibres aussi à la distillation et alambics en argile.",
   "Three categories help identify traditional methods. Mezcal allows any cooking, even pressurised steam, and any still, columns included. Artisanal requires pits or brick ovens, limited mills, fermentation with fibres in stone, wood or clay vessels, and directly heated pot stills. Ancestral means pits only, no mechanical mills, fibres in distillation too, and clay stills."),
  v:()=>spF([["Mezcal",w3("tutto ammesso","tout est permis","anything goes"),"#5c646b"],["Artesanal",w3("fossa o forno","fosse ou four","pit or brick oven"),"#d4a23a"],["Ancestral",w3("fossa, argilla","fosse, argile","pit, clay still"),"#8c1d40"]].map(([n,l,c],i)=>fD(.4+i*1,fBox(14+i*102,24,90,34,n,{fill:c,sz:10})+fT(59+i*102,76,l,9))).join("")
   +fD(1.2,spColumn(58,170,70,5,{steam:false,out:false}))+fD(2.2,spPotStill(144,170,.36,{cond:false}))+fD(3,spClayStill(264,166,1.1)))}
]},
/* ===================== s8 Vodka ===================== */
{id:"s2_vodka", sec:"c", ch:"s8", ic:"maps", t:I3_("Vodka","Vodka","Vodka"), s:[
 {h:I3_("Neutra e versatile","Neutre et polyvalente","Neutral and flexible"),
  c:I3_("Partita dall'Europa orientale, la vodka è oggi uno dei distillati più venduti quasi ovunque. Il suo segreto è la neutralità: non si scontra con nulla e si mescola facilmente. In teoria si può fare con qualsiasi materia agricola, ma costi e attese dei consumatori riducono la scelta soprattutto a cereali e patate; di recente qualcuno ha provato anche l'uva.",
   "Partie d'Europe de l'Est, la vodka est aujourd'hui l'un des spiritueux les plus vendus presque partout. Son secret est la neutralité : elle ne heurte rien et se mélange facilement. En théorie, n'importe quelle matière agricole convient, mais les coûts et les attentes des consommateurs réduisent le choix surtout aux céréales et aux pommes de terre ; récemment, certains ont aussi essayé le raisin.",
   "Having started out in Eastern Europe, vodka is now one of the best-selling spirits almost everywhere. Its secret is neutrality: it clashes with nothing and mixes easily. In theory any agricultural material will do, but cost and consumer expectations narrow the choice mainly to grains and potatoes; recently some producers have also tried grapes."),
  v:()=>spF(spBottle(160,96,"rgba(230,240,255,.5)",{lab:"VODKA"})+fChip(160,22,w3("neutralità","neutralité","neutrality"),"#5c646b")
   +fD(.8,spBarley(40,170,1)+spBarley(62,170,.9,"#c9a24a")+fChip(56,186,w3("cereali","céréales","grains"),"#d4a23a","#2a1b20"))
   +fD(1.6,spPotato(250,150,1.3)+spPotato(282,160,1)+fChip(266,186,w3("patate","pommes de terre","potatoes"),"#8a5a33"))
   +fD(2.4,fBunch(270,70,1.6,"#7a8a3a")+fChip(270,46,w3("uva: novità","raisin : nouveauté","grapes: a novelty"),"#5e8c31")))},
 {h:I3_("Cereali ed enzimi","Céréales et enzymes","Grains and enzymes"),
  c:I3_("Orzo, frumento e segale sono colture chiave dell'Europa orientale. Il loro amido però non fermenta: va trasformato in zucchero. L'orzo maltato può fornire gli enzimi necessari, ma oggi molti distillatori comprano enzimi già pronti e li aggiungono ai cereali macinati e cotti in acqua. È un po' come usare il lievito di birra invece di coltivare il proprio lievito madre.",
   "Orge, blé et seigle sont des cultures clés en Europe de l'Est. Leur amidon ne fermente pourtant pas : il faut le transformer en sucre. L'orge maltée peut fournir les enzymes nécessaires, mais aujourd'hui beaucoup de distillateurs achètent des enzymes prêtes à l'emploi et les ajoutent aux céréales broyées et cuites dans l'eau. Un peu comme utiliser de la levure du commerce plutôt qu'un levain maison.",
   "Barley, wheat and rye are key crops in Eastern Europe. Their starch cannot ferment, though: it must first become sugar. Malted barley can supply the enzymes needed, but many distillers now buy commercially prepared enzymes and add them to grains that have been crushed and cooked in water. It is a bit like using bought yeast instead of raising your own starter."),
  v:()=>spF(spBarley(30,150,.8)+spBarley(50,150,.8,"#d9c27a")+spBarley(70,150,.8,"#c9a24a")+fChip(50,170,w3("orzo, frumento, segale","orge, blé, seigle","barley, wheat, rye"))
   +fD(.8,fArrow("M96 110H120")+fTank(124,70,70,90,{col:"#e9e0c0",bub:6})+fHeater(159,176)+fChip(159,56,w3("macinati e cotti","broyés et cuits","crushed and cooked")))
   +fD(1.8,`<rect x="232" y="90" width="26" height="34" rx="3" fill="#fbf3e2"/>`+fT(245,112,"E",14,"#8c1d40")+spPour(245,90,196,80,"#f3cd8a",2)+fChip(250,140,w3("enzimi","enzymes","enzymes"),"#8c1d40"))
   +fD(2.6,fChip(250,178,w3("amido → zucchero","amidon → sucre","starch → sugar"),"#5e8c31")))},
 {h:I3_("Patate, tradizione polacca","Pommes de terre, tradition polonaise","Potatoes, a Polish tradition"),
  c:I3_("In Polonia la patata è una materia prima tradizionale. Il tubero conserva amido e richiede due tappe. Prima si cuoce in acqua finché si disfa completamente: l'amido diventa solubile e si ottiene un liquido torbido. Poi si aggiungono enzimi acquistati, che trasformano l'amido in zucchero pronto per il lievito.",
   "En Pologne, la pomme de terre est une matière première traditionnelle. Le tubercule stocke de l'amidon et demande deux étapes. D'abord, on le cuit dans l'eau jusqu'à ce qu'il se défasse complètement : l'amidon devient soluble et on obtient un liquide trouble. Ensuite, on ajoute des enzymes achetées, qui transforment l'amidon en sucre prêt pour la levure.",
   "In Poland, potatoes are a traditional raw material. The tuber stores starch and needs two steps. First it is cooked in water until it breaks down completely: the starch becomes soluble and the result is a cloudy liquid. Then bought-in enzymes are added to turn that starch into sugar ready for the yeast."),
  v:()=>spF(spPotato(40,90,1.4)+spPotato(64,100,1)+fChip(52,124,w3("Polonia","Pologne","Poland"),"#8c1d40")
   +fD(.8,fChip(150,26,"1",undefined)+fTank(118,50,70,100,{col:"#d8cfb4"})+fHeater(153,166)+fChip(153,186,w3("liquido torbido","liquide trouble","cloudy liquid")))
   +fD(2,fChip(256,26,"2")+`<rect x="236" y="56" width="26" height="34" rx="3" fill="#fbf3e2"/>`+fT(249,78,"E",14,"#8c1d40")+fArrow("M246 96V124")+fCrystals(234,146)+fChip(256,186,w3("enzimi → zucchero","enzymes → sucre","enzymes → sugar"),"#5e8c31")))},
 {h:I3_("95–96%: serve la colonna","95–96 % : il faut la colonne","95–96%: it takes a column"),
  c:I3_("La vodka nasce da uno spirito neutro, distillato almeno al 95% negli Stati Uniti e al 96% nell'Unione europea. A quel grado restano così pochi congeneri che l'aroma è neutro. Solo una colonna con abbastanza piatti ci arriva, mai un alambicco discontinuo da solo. Il processo è di solito continuo, e alcuni aggiungono passaggi per uno spirito ancora più puro e morbido.",
   "La vodka naît d'un alcool neutre, distillé à au moins 95 % aux États-Unis et 96 % dans l'Union européenne. À ce degré, il reste si peu de congénères que l'arôme est neutre. Seule une colonne avec assez de plateaux y parvient, jamais un alambic à repasse seul. Le procédé est généralement continu, et certains ajoutent des étapes pour un alcool encore plus pur et soyeux.",
   "Vodka is made from neutral spirit, distilled to at least 95% abv in the USA and 96% in the EU. At that level so few congeners remain that the aroma is neutral. Only a column with enough plates can get there, never a pot still alone. The process is usually continuous, and some add further steps for an even purer, smoother spirit."),
  v:()=>spF(spColumn(80,176,156,12,{liq:"#dfe9f0"})+fD(.8,spAbv(160,170,120,96,"","#9fd3f0",.8))+fD(1.6,fChip(240,50,"USA ≥ 95%","#3f7fa8")+fChip(240,80,"UE / EU ≥ 96%","#3f7fa8"))
   +fD(2.4,spPotStill(220,170,.3,{cond:false})+spNo(220,150,16)+fT(270,150,w3("non basta","ne suffit pas","not enough"),9,"#f3cd8a")))},
 {h:I3_("Alambicco ibrido e spirito acquistato","Alambic hybride et alcool acheté","Hybrid stills and bought-in spirit"),
  c:I3_("Ci sono varianti. Alcuni piccoli distillatori fanno una prima passata in alambicco e la seconda in colonna, senza effetti sul gusto. Altri non distillano affatto e comprano spirito neutro, una merce molto scambiata. Diluito e basta può risultare un po' ruvido, così lo si ripassa in un alambicco ibrido, cioè un alambicco collegato a una colonna di rettifica: la consistenza diventa più setosa.",
   "Il existe des variantes. Certains petits distillateurs font une première passe en alambic et la seconde en colonne, sans effet sur le goût. D'autres ne distillent pas du tout et achètent de l'alcool neutre, une marchandise très échangée. Simplement dilué, il peut sembler un peu rêche ; on le repasse donc dans un alambic hybride, relié à une colonne de rectification : la texture devient plus soyeuse.",
   "There are variations. Some small distillers make a first distillation in a pot and finish in a column, with no effect on flavour. Others do not distil at all and buy neutral spirit, a widely traded commodity. Simply diluted it can feel slightly rough, so it is run through a hybrid still, a pot linked to a rectifying column, for a silkier texture."),
  v:()=>spF(`<rect x="14" y="70" width="64" height="44" rx="4" fill="url(#fst)" stroke="#5c646b"/>`+fT(46,96,w3("spirito neutro","alcool neutre","neutral spirit"),8,"#2a1b20")+fChip(46,130,w3("acquistato","acheté","bought in"),"#5c646b")+fD(.6,fArrow("M82 92H104"))
   +fD(1,spPotStill(144,170,.5,{cond:false,vap:false})+`<path d="M152 128Q170 100 196 96" stroke="#9aa3ab" stroke-width="3" fill="none"/>`+spColumn(212,170,120,9,{steam:false,liq:"#dfe9f0"})+fChip(176,186,w3("alambicco ibrido","alambic hybride","hybrid still"),"#8c1d40"))
   +fD(2.4,fChip(276,40,w3("più setosa","plus soyeuse","silkier"),"#5e8c31")))},
 {h:I3_("Carbone, additivi, acqua","Charbon, additifs, eau","Charcoal, additives, water"),
  c:I3_("Molti produttori si limitano a diluire, convinti che la distillazione basti. Altri filtrano su carbone attivo, che toglie gli ultimi congeneri indesiderati, e usano additivi forniti da specialisti, su misura per ogni marca, per la consistenza e a volte un aroma lievissimo. A 40% quasi il 60% della bottiglia è acqua aggiunta: deve essere purissima.",
   "Beaucoup de producteurs se contentent de diluer, convaincus que la distillation suffit. D'autres filtrent sur charbon actif, qui retire les derniers congénères indésirables, et emploient des additifs fournis par des spécialistes, sur mesure pour chaque marque, pour la texture et parfois un arôme très léger. À 40 %, près de 60 % de la bouteille est de l'eau ajoutée : elle doit être très pure.",
   "Many producers simply dilute, believing distillation alone is enough. Others filter through activated charcoal, which removes any remaining unwanted congeners, and use additives from specialist suppliers, tailored to each brand, for texture and sometimes a very faint aroma. At 40% abv nearly 60% of the bottle is added water, so it must be extremely pure."),
  v:()=>spF(spCharcoal(20,40,60)+fChip(50,120,w3("carbone attivo","charbon actif","activated charcoal"))
   +fD(1,`<rect x="124" y="60" width="22" height="30" rx="3" fill="#fbf3e2"/><rect x="128" y="68" width="14" height="3" fill="#8c1d40"/>`+fDrops(135,92,120,"#f3cd8a",2)+fChip(140,140,w3("additivi","additifs","additives"),"#8c1d40")+fT(140,162,w3("consistenza","texture","texture"),9))
   +fD(2,`<rect x="214" y="40" width="70" height="130" rx="6" fill="url(#spgl)" stroke="#e8dccf"/><rect x="217" y="${168-125*.6}" width="64" height="${125*.6}" fill="#9fd3f0" opacity=".7"/><rect x="217" y="${168-125*.6-125*.4}" width="64" height="${125*.4}" fill="#eef3f6" opacity=".7"/>`+fT(249,88,"40%",11,"#2a1b20")+fT(249,134,w3("~60% acqua","~60 % eau","~60% water"),10,"#13302a")+fChip(249,186,w3("acqua purissima","eau très pure","very pure water"),"#3f7fa8")))},
 {h:I3_("Neutra o di carattere","Neutre ou de caractère","Neutral or characterful"),
  c:I3_("Le vodka non aromatizzate hanno due stili. Le neutre hanno il gusto più leggero possibile: non sono insapori, ma devono essere morbide, leggere e secche. Quelle di carattere conservano un po' più di sapore e una consistenza più piena. Un indizio utile: se una vodka liscia ha aromi chiaramente non neutri, quasi sempre sono stati aggiunti dopo la distillazione.",
   "Les vodkas non aromatisées ont deux styles. Les neutres ont le goût le plus léger possible : elles ne sont pas insipides, mais doivent être douces, légères et sèches. Celles de caractère gardent un peu plus de saveur et une texture plus ample. Un indice utile : si une vodka nature montre des arômes clairement non neutres, ils ont presque toujours été ajoutés après la distillation.",
   "Unflavoured vodkas come in two styles. Neutral vodkas have the lightest possible flavour: not tasteless, but smooth, light and dry. Characterful vodkas keep a little more flavour and a fuller, more mouthfilling texture. A useful clue: if an unflavoured vodka shows aromas that are clearly not neutral, they were almost certainly added after distillation."),
  v:()=>spF(spTulip(80,120,"rgba(230,240,255,.5)",1.3)+fChip(80,30,w3("neutra","neutre","neutral"),"#5c646b")+fChip(80,164,w3("leggera, secca","légère, sèche","light, dry"))
   +fD(1.2,spTulip(240,120,"rgba(240,236,220,.65)",1.3)+fChip(240,30,w3("di carattere","de caractère","characterful"),"#d4a23a","#2a1b20")+fChip(240,164,w3("più piena","plus ample","fuller texture")))
   +fD(2.4,fChip(160,190,w3("aroma netto = aggiunto","arôme net = ajouté","clear aroma = added"),"#8c1d40")))},
 {h:I3_("Le patrie della vodka","Les berceaux de la vodka","Vodka's homelands"),
  c:I3_("Storicamente la vodka è legata a Russia, Polonia, Finlandia e Svezia. Questi paesi ne producono ancora grandi volumi e molte delle vodka più apprezzate vengono da lì, spesso da cereali o, in Polonia, da patate. Oggi però si fa vodka in tutto il mondo, a ogni livello di qualità, e quasi ogni paese produttore ha esempi eccellenti.",
   "Historiquement, la vodka est liée à la Russie, la Pologne, la Finlande et la Suède. Ces pays en produisent encore de grands volumes et beaucoup des vodkas les plus réputées en viennent, souvent de céréales ou, en Pologne, de pommes de terre. Mais aujourd'hui on fait de la vodka dans le monde entier, à tous les niveaux de qualité, et presque chaque pays producteur a d'excellents exemples.",
   "Historically vodka is linked to Russia, Poland, Finland and Sweden. These countries still make large volumes, and many of the most highly regarded vodkas come from there, often from grain or, in Poland, from potatoes. Today, though, vodka is made all over the world at every quality level, and almost every producing country has outstanding examples."),
  v:()=>spF(fSnow()+[[w3("Svezia","Suède","Sweden"),70,60],[w3("Finlandia","Finlande","Finland"),150,40],[w3("Polonia","Pologne","Poland"),110,112],[w3("Russia","Russie","Russia"),230,90]].map(([n,x,y],i)=>fD(.3+i*.4,spPin(x,y,"#b5334a")+fChip(x,y+20,n))).join("")
   +fD(2.4,fChip(160,176,w3("ottime ovunque","excellentes partout","great ones everywhere"),"#5e8c31")),"winter")}
]},
/* ===================== f1 Gin ===================== */
{id:"s2_gin", sec:"s", ch:"f1", ic:"order", t:I3_("Gin","Gin","Gin"), s:[
 {h:I3_("Il ginepro prima di tutto","Le genièvre avant tout","Juniper comes first"),
  c:I3_("Il gin è uno spirito aromatizzato con ingredienti vegetali chiamati botaniche: erbe, semi, radici, scorze e spezie. Una sola è obbligatoria per legge: la bacca di ginepro, con il suo profumo resinoso, quasi di pineta, che rende il gin riconoscibile al primo sorso. Su tutto il resto il distillatore è libero.",
   "Le gin est un spiritueux aromatisé avec des ingrédients végétaux appelés botaniques : herbes, graines, racines, zestes et épices. Une seule est obligatoire selon la loi : la baie de genièvre, avec son parfum résineux, presque de forêt de pins, qui rend le gin reconnaissable dès la première gorgée. Pour tout le reste, le distillateur est libre.",
   "Gin is a spirit flavoured with plant ingredients known as botanicals: herbs, seeds, roots, peels and spices. Only one is required by law: the juniper berry, with the resinous, almost pine-forest scent that makes gin recognisable from the first sip. For everything else, the distiller has complete freedom."),
  v:()=>spF(spJuniper(110,100,2.4)+fD(.8,fChip(110,30,w3("ginepro: obbligatorio","genièvre : obligatoire","juniper: required"),"#3d4f8a"))
   +fD(1.6,fChip(110,170,w3("resinoso, pino","résineux, pin","resinous, pine"),"#5e8c31"))
   +fD(2.4,spBottle(250,110,"rgba(230,240,255,.5)",{lab:"GIN"})+fChip(250,170,w3("il resto è libero","le reste est libre","the rest is free"),"#d4a23a","#2a1b20")))},
 {h:I3_("Le botaniche più comuni","Les botaniques courantes","The usual botanicals"),
  c:I3_("Accanto al ginepro, alcune botaniche compaiono quasi in ogni ricetta. I semi di coriandolo danno note speziate e agrumate; le scorze di limone o arancia portano freschezza. Le radici di angelica e di iris hanno note terrose e floreali e tengono insieme gli altri aromi, come le fondamenta di una casa. Negli ultimi anni i distillatori hanno sperimentato moltissimo con erbe locali e frutti insoliti.",
   "À côté du genièvre, quelques botaniques reviennent dans presque toutes les recettes. Les graines de coriandre apportent des notes épicées et citronnées ; les zestes de citron ou d'orange, de la fraîcheur. Les racines d'angélique et d'iris ont des notes terreuses et florales et lient les autres arômes, comme les fondations d'une maison. Ces dernières années, les distillateurs ont beaucoup expérimenté avec herbes locales et fruits insolites.",
   "Alongside juniper, a handful of botanicals turn up in almost every recipe. Coriander seeds bring spicy, citrusy notes; lemon or orange peel adds freshness. Angelica and orris roots have earthy, floral notes and bind the other aromas together, like the foundations of a house. In recent years distillers have experimented widely with local herbs and unusual fruits."),
  v:()=>spF(spJuniper(160,104,1.3)+[[spSeeds(40,40),w3("coriandolo","coriandre","coriander"),50,80],[spPeel(270,50,LEMON)+spPeel(262,66,ORANGE),w3("scorze di agrumi","zestes d'agrumes","citrus peel"),266,90],[spRoot(44,120,"#a87a4a"),w3("angelica","angélique","angelica"),50,176],[spRoot(262,120,"#c9a8d0"),w3("iris","iris","orris"),266,176]].map(([g,l,x,y],i)=>fD(.5+i*.5,g+fChip(x,y,l))).join("")
   +fD(2.8,fChip(160,176,w3("tengono insieme","lient le tout","binding notes"),"#8a5a33")))},
 {h:I3_("La base: UE e USA","La base : UE et USA","The base: EU and USA"),
  c:I3_("Il gin non parte da una materia prima ma da uno spirito già pronto. Quasi tutti usano uno spirito neutro: su una tela bianca il ginepro e le altre botaniche risaltano. Nell'Unione europea è obbligatorio. Negli Stati Uniti si possono usare anche altri distillati con un po' di carattere, oppure distillare il gin direttamente da un liquido fermentato.",
   "Le gin ne part pas d'une matière première mais d'un spiritueux déjà fait. Presque tous utilisent un alcool neutre : sur une toile blanche, le genièvre et les autres botaniques ressortent. Dans l'Union européenne, c'est obligatoire. Aux États-Unis, on peut aussi utiliser d'autres eaux-de-vie avec un peu de caractère, ou distiller le gin directement à partir d'un liquide fermenté.",
   "Gin does not start from a raw material but from a finished spirit. Nearly everyone uses neutral spirit: against a blank canvas, juniper and the other botanicals stand out. In the European Union this is compulsory. In the United States, distillers may also use other spirits with some character, or distil gin straight from a fermented liquid."),
  v:()=>spF(`<rect x="40" y="30" width="90" height="70" rx="3" fill="#fbf6ec" stroke="#d8cdb8"/>`+fD(.6,spJuniper(85,66,.9))+fChip(85,118,w3("tela bianca","toile blanche","blank canvas"),"#5c646b")
   +fD(1.4,fBox(20,140,130,40,w3("UE: solo neutro","UE : neutre imposé","EU: neutral only"),{fill:"rgba(63,127,168,.75)"}))
   +fD(2.2,fBox(170,40,130,40,w3("USA: anche altri","USA : d'autres aussi","USA: others allowed"),{fill:"rgba(140,29,64,.7)"})+fTank(200,96,40,60,{col:"#d9c27a",bub:4})+fArrow("M244 130H262")+spBottle(284,140,"rgba(230,240,255,.5)",{s:.5})+fChip(240,186,w3("o da un fermentato","ou d'un fermenté","or from a ferment"))))},
 {h:I3_("1. Botaniche nel liquido","1. Botaniques dans le liquide","1. Botanicals in the liquid"),
  c:I3_("Il modo tradizionale di aromatizzare il gin è la ridistillazione: lo spirito neutro, diluito con acqua, torna nell'alambicco insieme alle botaniche, e i loro aromi salgono con il vapore. Nel primo metodo le botaniche stanno nel liquido. Alcuni le lasciano macerare prima di scaldare: più lungo il contatto, più sapore si estrae e più il gin diventa pieno, come una tisana lasciata in infusione.",
   "La façon traditionnelle d'aromatiser le gin est la redistillation : l'alcool neutre, dilué à l'eau, retourne dans l'alambic avec les botaniques, et leurs arômes montent avec la vapeur. Dans la première méthode, les botaniques sont dans le liquide. Certains les laissent macérer avant de chauffer : plus le contact est long, plus on extrait de saveur et plus le gin est ample, comme une tisane qui infuse.",
   "The traditional way to flavour gin is redistillation: neutral spirit, diluted with water, goes back into the still with the botanicals, and their aromas rise with the vapour. In the first method the botanicals sit in the liquid. Some distillers let them steep before heating: the longer the contact, the more flavour is extracted and the fuller the gin, like a herbal tea left to brew."),
  v:()=>spF(spPotStill(80,150,.95,{liq:"#e9e6d0"})+spBotDots(48,108,128,10)+fD(.8,fCall(80,130,60,40,w3("botaniche nel liquido","botaniques dans le pot","botanicals in the pot")))
   +fD(1.8,fClock(250,60,w3("macerazione","macération","steeping")))+fD(2.6,fChip(250,120,w3("gin più pieno","gin plus ample","fuller gin"),"#5e8c31")))},
 {h:I3_("2. Il cestello nel vapore","2. Le panier dans la vapeur","2. A basket in the vapour"),
  c:I3_("Nel secondo metodo le botaniche stanno in un cestello montato nel tubo tra alambicco e condensatore. Non toccano mai il liquido bollente: solo i vapori alcolici le attraversano e ne raccolgono gli aromi. Si estrae meno, quindi il gin è più leggero e delicato. Questi alambicchi sono a volte chiamati Carterhead.",
   "Dans la deuxième méthode, les botaniques sont dans un panier placé dans le tube entre l'alambic et le condenseur. Elles ne touchent jamais le liquide bouillant : seules les vapeurs alcooliques les traversent et emportent leurs arômes. On extrait moins, donc le gin est plus léger et délicat. Ces alambics sont parfois appelés Carterhead.",
   "In the second method the botanicals sit in a basket fitted in the pipe linking the still to the condenser. They never touch the boiling liquid: only the alcoholic vapours pass through them and pick up their aromas. Less is extracted, so the gin is lighter and more delicate. These stills are sometimes called Carterhead stills."),
  v:()=>spF(spPotStill(80,150,.95,{liq:"#e9e6d0"})+fD(.6,spBasket(80,150,.95))+fD(1.4,fCall(126,58,150,24,w3("cestello","panier","basket")))
   +fD(2.2,fChip(250,120,w3("gin più leggero","gin plus léger","lighter gin"),"#3f7fa8"))+fD(2.8,fChip(250,150,"Carterhead","#5c646b")))},
 {h:I3_("3. Distillare separatamente","3. Distiller séparément","3. Distilling separately"),
  c:I3_("Il terzo metodo distilla le botaniche una a una o a piccoli gruppi. Distillate insieme interagiscono e i loro aromi cambiano durante il processo; da sole danno sapori più puri. Alcuni distillano quasi tutto insieme e aggiungono un singolo distillato per farlo risaltare; altri lavorano ogni botanica a parte e assemblano tutto alla fine.",
   "La troisième méthode distille les botaniques une à une ou en petits groupes. Distillées ensemble, elles interagissent et leurs arômes changent pendant le processus ; seules, elles donnent des saveurs plus pures. Certains distillent presque tout ensemble et ajoutent un seul distillat pour le faire ressortir ; d'autres traitent chaque botanique à part et assemblent tout à la fin.",
   "The third method distils botanicals one by one or in small groups. Distilled together they interact and their aromas change during the process; alone they give purer flavours. Some distillers run most botanicals together and add a single separate distillate to make it stand out; others process every botanical individually and blend everything at the end."),
  v:()=>spF([["#3d4f8a",w3("ginepro","genièvre","juniper")],["#d6b77a",w3("coriandolo","coriandre","coriander")],["#f39a2b",w3("scorza","zeste","peel")]].map(([c,l],i)=>fD(i*.5,spPotStill(36+i*86,96,.4,{liq:mixC(c,"#ffffff",.5),cond:false})+fChip(40+i*86,120,l,c))).join("")
   +fD(1.8,[0,1,2].map(i=>spPour(40+i*86,130,160,150,"rgba(230,240,255,.8)",2)).join("")+fTank(134,140,52,50,{col:"rgba(230,240,255,.55)"})+fChip(250,170,w3("assemblaggio finale","assemblage final","blended at the end"),"#8c1d40"))
   +fD(2.6,fChip(250,30,w3("sapori più puri","saveurs plus pures","purer flavours"),"#5e8c31")))},
 {h:I3_("Incolore… o dorato","Incolore… ou doré","Colourless… or golden"),
  c:I3_("Il gin si può fare anche aggiungendo aromi artificiali, ma i migliori nascono dalla ridistillazione con botaniche vere. Dopo l'aromatizzazione quasi tutti riposano in recipienti inerti, vengono diluiti e imbottigliati incolori. C'è però una tendenza piccola ma in crescita: alcuni gin passano in botte di rovere e prendono un colore giallo paglierino e qualche nota di legno.",
   "On peut faire du gin en ajoutant des arômes artificiels, mais les meilleurs naissent de la redistillation avec de vraies botaniques. Après l'aromatisation, presque tous reposent en cuves inertes, sont dilués et mis en bouteille incolores. Une tendance petite mais croissante existe pourtant : certains gins passent en fût de chêne et prennent une couleur citron pâle et quelques notes boisées.",
   "Gin can be made by adding artificial flavourings, but the best come from redistillation with real botanicals. After flavouring, most rest in inert vessels, are diluted and bottled colourless. There is, however, a small but growing trend: some gins rest in oak casks and take on a pale lemon colour and some woody notes."),
  v:()=>spF(spSteel(30,60,60,90)+fArrow("M96 110H116")+spBottle(140,110,"rgba(230,240,255,.5)",{s:.75,lab:"GIN"})+fChip(110,180,w3("incolore","incolore","colourless"),"#5c646b")
   +fD(1.4,fBarrel(220,100,.6)+fArrow("M246 110H262")+spBottle(286,110,"#f3e6a0",{s:.75,lab:"GIN"})+fChip(250,180,w3("giallo pallido","citron pâle","pale lemon"),"#d4a23a","#2a1b20")))},
 {h:I3_("London Dry Gin","London Dry Gin","London Dry Gin"),
  c:I3_("London Dry Gin, o semplicemente Dry Gin, è lo stile definito più rigorosamente nell'Unione europea. Tutto il sapore deve venire dalla ridistillazione con le botaniche: dopo non si aggiunge nulla, e non può essere zuccherato. Nonostante il nome non è un'origine: si può fare ovunque, purché si segua il metodo. Di solito il termine è ben visibile in etichetta.",
   "Le London Dry Gin, ou simplement Dry Gin, est le style le plus strictement défini dans l'Union européenne. Toute la saveur doit venir de la redistillation avec les botaniques : rien n'est ajouté ensuite, et il ne peut pas être sucré. Malgré son nom, ce n'est pas une origine : on peut le faire partout, si l'on suit la méthode. La mention figure en général bien en vue sur l'étiquette.",
   "London Dry Gin, or simply Dry Gin, is the most tightly defined style in the European Union. All of its flavour must come from redistillation with botanicals: nothing is added afterwards, and it cannot be sweetened. Despite the name it is not a place of origin: it can be made anywhere, as long as the method is followed. The term usually appears prominently on the label."),
  v:()=>spF(spBottle(70,100,"rgba(230,240,255,.5)",{lab:"LONDON DRY",s:1.2})+fD(.8,fChip(214,40,w3("solo ridistillazione","que redistillation","redistillation only"),"#5e8c31"))
   +fD(1.6,spSugar(200,84,2)+spNo(206,74,14)+fChip(250,110,w3("niente zucchero","pas de sucre","no sugar"),"#8c1d40"))
   +fD(2.4,spPin(250,160,"#b5334a")+spNo(250,150,12)+fChip(250,186,w3("non è un'origine","pas une origine","not an origin"))))},
 {h:I3_("Distilled Gin e Old Tom","Distilled Gin et Old Tom","Distilled Gin and Old Tom"),
  c:I3_("Distilled Gin cambia significato tra i continenti. Nell'UE è un gin ridistillato con botaniche a cui si possono aggiungere altri aromi dopo. Negli USA invece tutto il sapore deve venire dalla ridistillazione, come per il London Dry europeo. Old Tom è uno stile più antico dei gin secchi: non è definito per legge, ma in etichetta indica di solito un gin zuccherato.",
   "Distilled Gin change de sens selon le continent. Dans l'UE, c'est un gin redistillé avec des botaniques, auquel on peut ajouter d'autres arômes. Aux États-Unis, au contraire, toute la saveur doit venir de la redistillation, comme pour le London Dry européen. Old Tom est un style plus ancien que les gins secs : il n'est pas défini par la loi, mais sur l'étiquette il indique en général un gin sucré.",
   "Distilled Gin changes meaning between continents. In the EU it is a gin redistilled with botanicals that may have further flavourings added afterwards. In the USA, by contrast, all the flavour must come from redistillation, close to the European London Dry. Old Tom is a style older than dry gins: not legally defined, but on a label it usually signals a sweetened gin."),
  v:()=>spF(fChip(90,24,"Distilled Gin","#8c1d40")+fBox(14,44,74,58,w3("UE: aromi dopo ok","UE : arômes après ok","EU: flavours after OK"),{fill:"rgba(63,127,168,.75)"})+fBox(96,44,74,58,w3("USA: solo ridistillato","USA : que redistillé","USA: redistilled only"),{fill:"rgba(94,140,49,.75)"})
   +fD(1.8,spBottle(250,100,"#f3ead0",{lab:"OLD TOM"})+spSugar(222,176,2)+fChip(250,30,"Old Tom","#d4a23a","#2a1b20")+fChip(250,154,w3("zuccherato","sucré","sweetened"),"#5e8c31"))
   +fD(2.6,fChip(92,140,w3("stesso nome","même nom","same words"),"#5c646b")+fChip(92,166,w3("regole diverse","règles différentes","different rules"),"#5c646b")))}
]},
/* ===================== f2 Other flavoured spirits ===================== */
{id:"s2_flavoured", sec:"s", ch:"f2", ic:"order", t:I3_("Aromatizzati: tecniche e famiglie","Aromatisés : techniques et familles","Flavoured spirits: methods and families"), s:[
 {h:I3_("Aromi naturali o artificiali","Arômes naturels ou artificiels","Natural or artificial flavours"),
  c:I3_("Gli aromi aggiunti a uno spirito sono di due famiglie. Quelli naturali vengono da frutta o botaniche, cioè erbe e spezie. Il produttore può estrarli da sé o comprarli già pronti da specialisti. Quelli artificiali sono creati dall'uomo ma imitano sapori della natura; anche questi si acquistano da fornitori specializzati.",
   "Les arômes ajoutés à un spiritueux forment deux familles. Les naturels viennent de fruits ou de botaniques, c'est-à-dire d'herbes et d'épices. Le producteur peut les extraire lui-même ou les acheter tout prêts à des spécialistes. Les artificiels sont créés par l'homme mais imitent des saveurs de la nature ; eux aussi s'achètent auprès de fournisseurs spécialisés.",
   "Flavours added to a spirit fall into two families. Natural ones come from fruit or botanicals, meaning herbs and spices. Producers can extract them themselves or buy them ready-made from specialists. Artificial ones are man-made but imitate flavours found in nature; they too are bought from specialist suppliers."),
  v:()=>spF(fChip(80,24,w3("naturali","naturels","natural"),"#5e8c31")+spCherry(50,90,1.3)+spStarAnise(100,80,1)+fLeaf(70,120,1.2,10,"#4f9a3a")+spCitrus(110,124,10,ORANGE)
   +fD(1.2,fChip(240,24,w3("artificiali","artificiels","artificial"),"#8c1d40")+`<path d="M226 60H254V74L268 120Q270 128 262 128H218Q210 128 212 120L226 74Z" fill="url(#spgl)" stroke="#e8dccf"/><path d="M216 112H264L268 122Q268 126 262 126H218Q212 126 214 120Z" fill="#e2622a" opacity=".8"/>`+fChip(240,150,w3("imitano la natura","imitent la nature","imitate nature")))
   +fD(2.2,fChip(160,184,w3("fatti o comprati","faits ou achetés","made or bought in"),"#5c646b")))},
 {h:I3_("Macerazione: la tintura","Macération : la teinture","Maceration: the tincture"),
  c:I3_("Nella macerazione frutta o botaniche restano immerse nell'alcol da poche ore a diversi mesi, a volte con un leggero calore; spesso stanno in sacchetti per toglierle facilmente. Se l'alcol è troppo forte estrae sapori sgradevoli, quindi uno spirito molto rettificato si diluisce prima. La macerazione estrae colore e un'ampia gamma di sapori, ma non isola un aroma preciso. Il risultato si chiama tintura.",
   "Dans la macération, fruits ou botaniques trempent dans l'alcool de quelques heures à plusieurs mois, parfois avec une douce chaleur ; souvent dans des sacs pour les retirer facilement. Trop fort, l'alcool extrait des saveurs désagréables : un alcool très rectifié est donc dilué d'abord. La macération extrait couleur et large gamme de saveurs, mais n'isole pas un arôme précis. Le résultat s'appelle teinture.",
   "In maceration, fruit or botanicals soak in alcohol for a few hours to several months, sometimes with gentle heat, often in bags so they are easy to remove. Too strong an alcohol extracts unpleasant flavours, so highly rectified spirit is diluted first. Maceration extracts colour and a broad range of flavours, but cannot isolate one aroma. The result is called a tincture."),
  v:()=>spF(fTank(40,50,100,120,{col:"#c98a3a",colTo:"#9a4a1a",cd:5,cb:.5})+spBag(74,112)+spBag(106,120)+fD(1,fClock(200,50,w3("ore → mesi","heures → mois","hours → months")))
   +fD(1.8,fChip(240,104,w3("colore + sapori","couleur + saveurs","colour + flavours"),"#5e8c31")+fChip(240,130,w3("niente isolamento","pas d'isolement","no isolating"),"#8c1d40"))
   +fD(2.6,fChip(240,170,w3("tintura","teinture","tincture"),"#d4a23a","#2a1b20")))},
 {h:I3_("Ridistillazione e sottovuoto","Redistillation et sous vide","Redistillation and vacuum"),
  c:I3_("Nella ridistillazione lo spirito, di solito neutro e diluito, torna in alambicco con frutta o botaniche, a volte dopo una breve macerazione. Gli aromi più volatili escono per primi, i meno volatili per ultimi: il distillatore sceglie il cuore quando passano quelli voluti. Il risultato si chiama distillato. Per botaniche delicate, come il cetriolo, l'alambicco sottovuoto bolle a temperatura più bassa e le rispetta.",
   "En redistillation, l'alcool, souvent neutre et dilué, retourne à l'alambic avec fruits ou botaniques, parfois après une courte macération. Les plus volatils sortent en premier, les moins volatils en dernier : le distillateur choisit le cœur quand passent ceux qu'il veut. Le résultat s'appelle distillat. Pour des botaniques fragiles, comme le concombre, l'alambic sous vide bout à plus basse température et les préserve.",
   "In redistillation the spirit, usually diluted neutral spirit, goes back into the still with fruit or botanicals, sometimes after a short maceration. The most volatile aromas come off first, the least volatile last: the distiller takes the hearts cut when the wanted aromas are flowing. The result is called a distillate. For fragile botanicals such as cucumber, a vacuum still boils at a lower temperature and protects them."),
  v:()=>spF(spPotStill(50,150,.7,{liq:"#e9e6d0"})+spBotDots(28,72,136,6)+fD(1,fChip(150,26,w3("cuore scelto","cœur choisi","hearts cut"),"#d4a23a","#2a1b20")+fChip(150,52,w3("distillato","distillat","distillate"),"#5e8c31"))
   +fD(2,`<rect x="226" y="80" width="64" height="70" rx="10" fill="url(#fst)" stroke="#5c646b"/><ellipse cx="258" cy="120" rx="16" ry="7" fill="#7fae46"/><ellipse cx="258" cy="120" rx="12" ry="4.5" fill="#cfe6a8"/>`+fGauge(258,56,-60,"")+fThermo(298,90,"",.25,"#3f7fa8")+fChip(258,170,w3("sottovuoto: freddo","sous vide : froid","vacuum: cooler"),"#3f7fa8")+fChip(258,194,w3("cetriolo","concombre","cucumber"),"#5e8c31")))},
 {h:I3_("Comprati, a freddo, assemblati","Achetés, à froid, assemblés","Bought, cold-compounded, blended"),
  c:I3_("Alcune marche non toccano mai le botaniche: comprano aromi naturali già pronti e li mescolano allo spirito. Gli aromi artificiali si uniscono allo spirito allo stesso modo, una tecnica detta compounding a freddo. Certi prodotti usano una sola tecnica e sono subito pronti; altri riuniscono diverse tinture e distillati preparati separatamente, poi assemblati.",
   "Certaines marques ne touchent jamais aux botaniques : elles achètent des arômes naturels tout prêts et les mélangent à l'alcool. Les arômes artificiels s'ajoutent de la même façon, une technique appelée compounding à froid. Certains produits n'utilisent qu'une technique et sont prêts aussitôt ; d'autres réunissent plusieurs teintures et distillats préparés à part, puis assemblés.",
   "Some brands never handle botanicals at all: they buy ready-made natural flavourings and blend them into the spirit. Artificial flavours are mixed in the same way, a technique called cold compounding. Some products use just one technique and are ready straight away; others bring together several tinctures and distillates, made separately and then blended."),
  v:()=>spF(`<rect x="30" y="50" width="26" height="34" rx="3" fill="#fbf3e2"/><rect x="34" y="58" width="18" height="3" fill="#8c1d40"/>`+fDrops(43,86,116,"#e2622a",2)+spSteel(20,110,50,60)+fChip(46,186,w3("compounding a freddo","compounding à froid","cold compounding"),"#8c1d40")
   +fD(1.4,[["#c98a3a",w3("tintura","teinture","tincture")],["rgba(230,240,255,.7)",w3("distillato","distillat","distillate")],["#d9c27a",w3("distillato 2","distillat 2","distillate 2")]].map(([c,l],i)=>spBottle(150+i*44,64,c,{s:.5})+fT(150+i*44,98,l,8.5,"#f3cd8a")+spPour(150+i*44,110,216,140,c,2)).join("")+fTank(192,130,48,46,{col:"#d9b26a"})+fChip(250,190,w3("assemblaggio","assemblage","blending"),"#5e8c31")))},
 {h:I3_("Il colore","La couleur","Colour"),
  c:I3_("Anche il colore può essere naturale o artificiale. Quello estratto dalle piante per macerazione è instabile: può cambiare da una bottiglia all'altra, cosa che quasi nessun consumatore accetterebbe. Per questo anche i produttori di alta gamma usano spesso un po' di colorante artificiale. I coloranti alimentari approvati spiegano le tinte vivaci di molti liquori.",
   "La couleur aussi peut être naturelle ou artificielle. Celle extraite des plantes par macération est instable : elle peut varier d'une bouteille à l'autre, ce que presque aucun consommateur n'accepterait. C'est pourquoi même les producteurs haut de gamme utilisent souvent un peu de colorant artificiel. Les colorants alimentaires autorisés expliquent les teintes vives de nombreuses liqueurs.",
   "Colour, too, can be natural or artificial. Colour extracted from plants by maceration is unstable: it can vary from one bottle to the next, which almost no consumer would accept. That is why even premium producers often use some artificial colouring. Approved food colourings explain the vivid shades of many liqueurs."),
  v:()=>spF(["#7aa04a","#93a85a","#a8b070"].map((c,i)=>fD(i*.3,spBottle(36+i*40,90,c,{s:.6}))).join("")+fChip(76,140,w3("naturale: instabile","naturel : instable","natural: unstable"),"#8a5a33")
   +fD(1.4,["#1f6fd6","#19a35a","#c4123a","#f2b81a"].map((c,i)=>spBottle(196+i*34,90,c,{s:.55})).join("")+fChip(246,140,w3("artificiale: vivace","artificiel : vif","artificial: vivid"),"#3f7fa8"))
   +fD(2.4,fChip(160,184,w3("spesso entrambi","souvent les deux","often both"),"#5c646b")))},
 {h:I3_("Rum speziato e vodka aromatizzata","Rhum épicé et vodka aromatisée","Spiced rum and flavoured vodka"),
  c:I3_("Il rum speziato parte di solito da un rum dorato già zuccherato, con spezie come vaniglia e cannella; probabilmente per macerazione, perché ridistillare toglierebbe colore e carattere. La vodka aromatizzata è antica in Europa orientale: miele, frutta e spezie macerati, come l'erba di bisonte. Oggi le marche economiche usano aromi pronti; quelle di pregio macerano e poi ridistillano.",
   "Le rhum épicé part d'un rhum doré déjà sucré, avec vanille ou cannelle, sans doute par macération : redistiller ôterait couleur et caractère. La vodka aromatisée est ancienne en Europe de l'Est : miel, fruits et épices macérés, comme l'herbe de bison. Aujourd'hui, les marques bon marché utilisent des arômes tout prêts ; les haut de gamme macèrent puis redistillent.",
   "Spiced rum usually starts from an already sweetened golden rum, with spices such as vanilla and cinnamon, most likely added by maceration, because redistilling would strip colour and character. Flavoured vodka is old in Eastern Europe: honey, fruit and spices macerated, as with bison grass. Today cheap brands use ready-made flavourings; premium ones macerate, then redistil."),
  v:()=>spF(spBottle(50,90,"#c98a3a",{lab:"SPICED"})+`<path d="M86 120l40 -6" stroke="#2a1410" stroke-width="3"/><path d="M84 132q12 -4 24 0q12 4 24 0" stroke="#a0582a" stroke-width="4" fill="none"/>`+fChip(70,150,w3("vaniglia, cannella","vanille, cannelle","vanilla, cinnamon"),"#8a5a33")+fChip(70,176,w3("macerazione","macération","maceration"))
   +fD(1.6,spBottle(236,90,"rgba(230,240,255,.5)",{lab:"VODKA"})+`<path d="M236 50V120" stroke="#9cc65a" stroke-width="2.6"/>`+fChip(236,150,w3("erba di bisonte","herbe de bison","bison grass"),"#5e8c31"))
   +fD(2.6,fChip(236,176,w3("pregio: ridistilla","premium : redistille","premium: redistil"),"#d4a23a","#2a1b20")))},
 {h:I3_("Anice: anetolo e louche","Anis : anéthole et louche","Aniseed: anethole and louching"),
  c:I3_("Intorno al Mediterraneo si bevono pastis e assenzio in Francia, ouzo in Grecia, raki in Turchia. Li unisce l'anetolo, che dà il gusto di anice e viene soprattutto da anice verde, finocchio e anice stellato. Partono da uno spirito neutro, non invecchiano e sono colorati. Con l'acqua l'anetolo esce di soluzione e il liquido diventa torbido: è il louche, parte del rito del servizio.",
   "Autour de la Méditerranée : pastis et absinthe en France, ouzo en Grèce, raki en Turquie. Ils ont en commun l'anéthole, qui donne le goût anisé et vient surtout de l'anis vert, du fenouil et de la badiane. Ils partent d'un alcool neutre, ne vieillissent pas et sont colorés. Avec l'eau, l'anéthole sort de la solution et le liquide se trouble : c'est le louche, partie du rituel du service.",
   "Around the Mediterranean people drink pastis and absinthe in France, ouzo in Greece and raki in Turkey. They share anethole, which gives the aniseed taste and comes mainly from aniseed, fennel and star anise. They start from neutral spirit, are unaged and coloured. With water, anethole comes out of solution and the drink turns cloudy: louching, part of the serving ritual."),
  v:()=>spF(spStarAnise(40,50,1.3)+spFennel(90,110,.9)+spSeeds(28,120,"#c9b46a")+fChip(70,150,w3("anetolo","anéthole","anethole"),"#8c1d40")+fChip(70,176,"pastis · ouzo · raki")
   +fD(1.2,spJug(196,120,1,236,104))+fD(1.4,spLouche(260,150,1.8,1.6))+fD(2.6,fChip(260,30,w3("il louche","le louche","louching"),"#3f7fa8")))},
 {h:I3_("Pastis e assenzio","Pastis et absinthe","Pastis and absinthe"),
  c:I3_("Il pastis deve contenere liquirizia oltre ad anice, finocchio e anice stellato, ed è obbligatoriamente zuccherato: medio o dolce, colorato giallo, verde o verde-bruno. Prese il posto dell'assenzio quando questo fu vietato. Oggi l'assenzio è di nuovo permesso ma senza definizione legale: tradizionalmente non è zuccherato, contiene assenzio maggiore, amaro e floreale, e si diluisce fino al grado di un vino.",
   "Le pastis doit contenir de la réglisse en plus de l'anis, du fenouil et de la badiane, et il est obligatoirement sucré : moyen ou sucré, coloré jaune, vert ou vert-brun. Il a remplacé l'absinthe interdite. Aujourd'hui l'absinthe est de nouveau permise mais sans définition légale : traditionnellement non sucrée, avec de la grande absinthe, amère et florale, et diluée jusqu'au degré d'un vin.",
   "Pastis must contain liquorice as well as aniseed, fennel and star anise, and it must be sweetened: medium or sweet, coloured yellow, green or green-brown. It replaced absinthe when absinthe was banned. Absinthe is allowed again but has no legal definition: traditionally unsweetened, made with wormwood, floral and bitter, and diluted down to wine strength."),
  v:()=>spF(spBottle(60,86,"#e3c84a",{lab:"PASTIS"})+spLiquorice(60,140)+fChip(60,166,w3("liquirizia","réglisse","liquorice"),"#8a5a33")+fChip(60,190,w3("sempre zuccherato","toujours sucré","always sweet"),"#5e8c31")
   +fD(1.4,spBottle(220,86,"#8fb84a",{lab:"ABSINTHE"})+spWormwood(276,120,.9)+fChip(240,154,w3("assenzio maggiore","grande absinthe","wormwood"),"#5e8c31")+fChip(240,178,w3("non zuccherata","non sucrée","unsweetened"),"#8c1d40"))
   +fD(2.4,spSugar(150,40,1)+`<path d="M140 56h32" stroke="#c9ced3" stroke-width="2"/>`+fT(156,74,w3("a piacere","au goût","to taste"),9)))},
 {h:I3_("Gli amari: tre famiglie","Les amers : trois familles","Bitters: three families"),
  c:I3_("Gli amari sono spiriti, di solito neutri, con un evidente gusto amaro: chinino, genziana, arancia amara, carciofo. L'amaro non si sente al naso, solo sulla lingua; zucchero e altre botaniche lo bilanciano. Gli amari da aperitivo sono colorati e più dolci, in long drink o cocktail. Quelli digestivi sono intensi e amari, spesso lisci. Quelli da cocktail sono forti e concentrati, usati a gocce.",
   "Les amers sont des spiritueux, en général neutres, au goût amer évident : quinine, gentiane, orange amère, artichaut. L'amertume ne se sent pas au nez, seulement sur la langue ; le sucre et d'autres botaniques l'équilibrent. Les amers apéritifs sont colorés et plus sucrés, en long drink ou cocktail. Les digestifs sont intenses et amers, souvent purs. Les amers à cocktail sont forts et concentrés, utilisés en traits.",
   "Bitters are spirits, usually neutral, with an obvious bitter taste: quinine, gentian, bitter orange, artichoke. Bitterness cannot be smelled, only tasted on the tongue; sugar and other botanicals balance it. Aperitif bitters are colourful and sweeter, served long or in cocktails. Digestif bitters are intense and bitter, often drunk neat. Cocktail bitters are strong and concentrated, used in dashes."),
  v:()=>spF(spBark(30,30)+spGentian(70,20)+spPeel(110,30,"#e2622a")+spArtichoke(150,40,.8)+fT(90,72,w3("solo sulla lingua","seulement en bouche","tongue only"),9,"#f3cd8a")
   +fD(1,spCocktail(56,166,"highball","#c4123a",{ice:1,gar:ORANGE,s:.9})+fChip(56,190,w3("aperitivo","apéritif","aperitif"),"#c4123a"))
   +fD(1.8,spCocktail(160,166,"rocks","#3a1a10",{s:.9})+fChip(160,190,w3("digestivo","digestif","digestif"),"#8a5a33"))
   +fD(2.6,spBitters(262,150,1)+spTumbler(262,180,"#c98a3a",.5)+fChip(262,194,w3("da cocktail","à cocktail","cocktail"),"#5c646b")))}
]},
/* ===================== f3 Liqueurs ===================== */
{id:"s2_liqueurs", sec:"s", ch:"f3", ic:"order", t:I3_("Liquori","Liqueurs","Liqueurs"), s:[
 {h:I3_("Aromatizzato più zucchero","Aromatisé plus sucre","Flavoured plus sugar"),
  c:I3_("Un liquore è, in breve, uno spirito aromatizzato e zuccherato. È lo zucchero a distinguerlo da un semplice spirito aromatizzato. Il minimo di zucchero cambia da paese a paese, ma il risultato è sempre lo stesso: ogni liquore si descrive come dolce. In degustazione non esiste un liquore secco: se non è dolce, è un altro tipo di spirito aromatizzato.",
   "Une liqueur est, en bref, un spiritueux aromatisé et sucré. C'est le sucre qui la distingue d'un simple spiritueux aromatisé. Le minimum de sucre varie d'un pays à l'autre, mais le résultat est toujours le même : toute liqueur se décrit comme sucrée. En dégustation, il n'existe pas de liqueur sèche : si ce n'est pas sucré, c'est un autre type de spiritueux aromatisé.",
   "A liqueur is, in short, a flavoured spirit that has been sweetened. Sugar is what sets it apart from a plain flavoured spirit. The legal minimum varies from country to country, but the result is always the same: every liqueur is correctly described as sweet. In tasting there is no such thing as a dry liqueur; if it is not sweet, it is another kind of flavoured spirit."),
  v:()=>spF(spBottle(46,100,"rgba(230,240,255,.5)",{s:.75})+fT(46,150,w3("spirito","spiritueux","spirit"),9)+fT(96,104,"+",20,"#f3cd8a")+fD(.6,spCherry(130,100,1.2)+spStarAnise(138,70,.7)+fT(134,150,w3("aromi","arômes","flavours"),9))
   +fD(1.2,fT(170,104,"+",20,"#f3cd8a")+spSugar(200,104,2)+fT(206,150,w3("zucchero","sucre","sugar"),9))+fD(1.8,fT(236,104,"=",20,"#f3cd8a")+spBottle(276,100,"#b5153a",{s:.75}))
   +fD(2.4,fChip(160,30,w3("sempre dolce","toujours sucrée","always sweet"),"#5e8c31")+fChip(160,184,w3("minimo: varia","minimum : variable","minimum varies"),"#5c646b")))},
 {h:I3_("Una base neutra… o di carattere","Une base neutre… ou de caractère","A neutral base… or a characterful one"),
  c:I3_("La maggior parte dei liquori parte da uno spirito neutro, uno sfondo pulito che lascia brillare gli aromi aggiunti. Alcuni però scelgono una base di carattere: esistono liquori a base di Cognac o di whisky scozzese, dove lo spirito di partenza si sente e diventa parte dello stile.",
   "La plupart des liqueurs partent d'un alcool neutre, un fond propre qui laisse briller les arômes ajoutés. Certaines choisissent pourtant une base de caractère : il existe des liqueurs à base de Cognac ou de whisky écossais, où l'eau-de-vie de départ se goûte et devient une partie du style.",
   "Most liqueurs start from neutral spirit, a clean backdrop that lets the added flavours shine. Some, however, choose a characterful base: there are liqueurs built on Cognac or on Scotch whisky, where the starting spirit can be tasted and becomes part of the style."),
  v:()=>spF(spColumn(60,170,120,9,{steam:false,liq:"#dfe9f0"})+fChip(60,186,w3("di solito neutro","souvent neutre","usually neutral"),"#5c646b")
   +fD(1.2,fBarrel(200,80,.7)+fChip(200,120,"Cognac","#d4a23a","#2a1b20"))+fD(2,spBarley(270,140,.9)+fChip(270,154,"Scotch whisky","#8a5a33"))
   +fD(2.8,fChip(236,186,w3("si sente la base","la base se goûte","the base shows"),"#8c1d40")))},
 {h:I3_("Aromi senza limiti","Arômes sans limite","Flavours without limits"),
  c:I3_("Non ci sono limiti agli aromi. Alcuni produttori puntano su un solo gusto, un frutto o un seme; altri usano ricette complesse e spesso segrete, con decine di erbe e spezie. Si usano le tecniche già viste: macerazione, ridistillazione, aromi acquistati, spesso assemblando più preparazioni.",
   "Il n'y a pas de limite aux arômes. Certains producteurs misent sur un seul goût, un fruit ou une graine ; d'autres emploient des recettes complexes et souvent secrètes, avec des dizaines d'herbes et d'épices. On utilise les techniques déjà vues : macération, redistillation, arômes achetés, souvent en assemblant plusieurs préparations.",
   "There is no limit on flavourings. Some producers focus on a single taste, such as one fruit or seed; others use complex, often secret recipes with dozens of herbs and spices. The techniques are the ones already seen: maceration, redistillation and bought-in flavourings, often with several preparations blended together."),
  v:()=>spF(spCherry(60,100,2)+fChip(60,140,w3("un solo gusto","un seul goût","one flavour"),"#b5153a")
   +fD(1,[[170,60],[200,90],[230,56],[260,96],[190,130],[240,130],[280,60]].map(([x,y],i)=>i%3===0?fLeaf(x,y,.9,i*30,"#4f9a3a"):i%3===1?spStarAnise(x,y,.6):spSeeds(x-6,y-4,"#d6b77a")).join("")+fChip(226,166,w3("ricetta segreta","recette secrète","secret recipe"),"#5c646b"))
   +fD(2.2,fChip(160,190,w3("macerare, ridistillare","macérer, redistiller","macerate, redistil"))))},
 {h:I3_("La panna","La crème","Cream"),
  c:I3_("Un ingrediente speciale è la panna. È un'invenzione relativamente recente, degli anni Settanta, e richiede tecniche complesse perché non formi grumi in bottiglia. I liquori alla crema sono tra le pochissime bevande alcoliche davvero opache: in degustazione la loro intensità di colore si descrive proprio come opaca.",
   "Un ingrédient particulier est la crème. C'est une invention assez récente, des années 1970, et elle demande des techniques complexes pour ne pas former de grumeaux en bouteille. Les liqueurs à la crème font partie des très rares boissons alcoolisées vraiment opaques : en dégustation, leur intensité de couleur se décrit justement comme opaque.",
   "One special ingredient is cream. It is a relatively modern invention, from the 1970s, and needs complex techniques so that it does not form lumps in the bottle. Cream liqueurs are among the very few truly opaque alcoholic drinks: in tasting, their colour intensity is described precisely as opaque."),
  v:()=>spF(spCreamDrop(70,110,2.2)+fChip(70,150,w3("niente grumi","pas de grumeaux","no lumps"),"#8c1d40")
   +fD(1,spBottle(190,100,"#e8d8b8",{lab:"CREAM"})+spTulip(258,150,"#e8d8b8",1.2)+`<path d="M244 120Q258 112 272 120V133Q258 138 244 133Z" fill="#e8d8b8"/>`)
   +fD(2,fChip(226,30,w3("opaco","opaque","opaque"),"#d4a23a","#2a1b20")+fChip(70,30,w3("anni '70","années 1970","1970s"),"#5c646b")))},
 {h:I3_("Quattro famiglie","Quatre familles","Four families"),
  c:I3_("Per orientarsi tra centinaia di liquori conviene raggrupparli secondo l'aroma principale. Le quattro famiglie più utili sono: erbe; frutta; semi, frutta secca e noccioli; panna. Davanti a una bottiglia sconosciuta basta chiedersi da quale famiglia viene il gusto dominante: così è più facile confrontare due liquori e decidere come usarli.",
   "Pour s'y retrouver parmi des centaines de liqueurs, il vaut mieux les regrouper selon l'arôme principal. Les quatre familles les plus utiles sont : herbes ; fruits ; graines, fruits à coque et noyaux ; crème. Devant une bouteille inconnue, il suffit de se demander de quelle famille vient le goût dominant : il devient alors plus facile de comparer deux liqueurs et de choisir comment les utiliser.",
   "To find your way among hundreds of liqueurs, group them by their main flavour. The four most useful families are: herb; fruit; seed, nut and kernel; and cream. Faced with an unfamiliar bottle, ask which family its dominant flavour belongs to: that makes it much easier to compare two liqueurs and decide how to use them."),
  v:()=>spF([[fLeaf(0,10,1.6,0,"#4f9a3a"),w3("erbe","herbes","herb"),"#4f9a3a"],[spCherry(-4,10,1.3),w3("frutta","fruits","fruit"),"#b5153a"],[spNut(0,12,1.3),w3("semi, noci","graines, noix","seed, nut, kernel"),"#8a5a33"],[spCreamDrop(0,14,1.2),w3("panna","crème","cream"),"#c9b48a"]].map(([g,l,c],i)=>fD(.4+i*.6,`<g transform="translate(${44+i*77} 90)">${g}</g>`+fChip(44+i*77,i%2?150:128,l,c))).join("")
   +fD(3,fChip(160,184,w3("gusto dominante?","goût dominant ?","dominant flavour?"),"#5c646b")))},
 {h:I3_("Colore e grado","Couleur et degré","Colour and strength"),
  c:I3_("Il colore è facoltativo ma molto comune: i coloranti artificiali spiegano i blu elettrici, i verdi smeraldo e i rossi rubino dei banconi. Quanto al grado, quasi tutti gli spiriti hanno un minimo legale, circa 37,5% nell'UE e 40% negli USA. I liquori invece possono essere imbottigliati a un grado più basso.",
   "La couleur est facultative mais très courante : les colorants artificiels expliquent les bleus électriques, les verts émeraude et les rouges rubis des comptoirs. Côté degré, presque tous les spiritueux ont un minimum légal, environ 37,5 % dans l'UE et 40 % aux États-Unis. Les liqueurs, elles, peuvent être mises en bouteille à un degré plus bas.",
   "Colour is optional but very common: artificial colourings explain the electric blues, emerald greens and ruby reds on bar shelves. As for strength, most spirits have a legal minimum, about 37.5% abv in the EU and 40% in the USA. Liqueurs, however, may be bottled at a lower strength."),
  v:()=>spF(["#1f6fd6","#19a35a","#c4123a"].map((c,i)=>fD(i*.3,spBottle(36+i*44,90,c,{s:.65}))).join("")+fChip(80,144,w3("colore facoltativo","couleur facultative","colour optional"),"#5c646b")
   +fD(1.4,spAbv(200,160,100,40,w3("spiriti","spiritueux","spirits"),"#d4a23a",1.4)+spAbv(270,160,100,20,w3("liquori","liqueurs","liqueurs"),"#c4123a",1.8))
   +fD(2.8,fChip(236,30,"UE 37,5% · USA 40%","#3f7fa8")))},
 {h:I3_("Conservare una bottiglia aperta","Garder une bouteille ouverte","Keeping an open bottle"),
  c:I3_("Prima di aprirle, le bottiglie stanno meglio al fresco, a temperatura costante e lontano dalla luce. Una volta aperte, l'ossigeno le degrada lentamente, più in fretta quando sono a meno di metà. I liquori a basso grado perdono freschezza prima degli altri: vanno usati in tempi più brevi.",
   "Avant ouverture, les bouteilles se gardent au frais, à température constante et loin de la lumière. Une fois ouvertes, l'oxygène les dégrade lentement, plus vite quand elles sont à moins de la moitié. Les liqueurs à faible degré perdent leur fraîcheur avant les autres : il faut les utiliser plus rapidement.",
   "Before opening, bottles are best kept cool, at a constant temperature and away from sunlight. Once opened, oxygen slowly degrades them, faster once the bottle is less than half full. Lower-strength liqueurs lose their freshness sooner than other spirits, so they should be used up more quickly."),
  v:()=>spF(fThermo(30,50,"",.3,"#3f7fa8")+fSun(90,50,10)+spNo(90,50,18)+fChip(60,140,w3("fresco, al buio","au frais, à l'ombre","cool, dark"),"#3f7fa8")
   +fD(1.2,spBottle(190,100,"#c4123a",{s:.85})+`<rect x="179" y="70" width="22" height="18" fill="#2a1b17" opacity=".7"/>`+[0,1,2].map(i=>`<text x="${170+i*14}" y="50" font-size="7" fill="#9fd3f0" text-anchor="middle" font-weight="800">O₂<animate attributeName="y" from="40" to="80" dur="2.4s" begin="${i*.6}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;0" dur="2.4s" begin="${i*.6}s" repeatCount="indefinite"/></text>`).join("")+fChip(190,160,w3("mezza vuota: più aria","à moitié vide : + d'O₂","half empty: more air"),"#8c1d40"))
   +fD(2.4,fClock(282,90,"")+fChip(276,186,w3("usare presto","à finir vite","use sooner"),"#5e8c31")))}
]},
/* ===================== f4 Vermouth ===================== */
{id:"s2_vermouth", sec:"s", ch:"f4", ic:"grapes", t:I3_("Il vermouth","Le vermouth","Vermouth"), s:[
 {h:I3_("Un vino, non uno spirito","Un vin, pas un spiritueux","A wine, not a spirit"),
  c:I3_("I vini aromatizzati non sono spiriti, ma al bar si usano di continuo, e il più importante è il vermouth. Tutti partono da un vino, aromatizzato con botaniche e portato a un grado più alto con alcol distillato. Di solito sono zuccherati e possono essere colorati. È il vermouth che i cocktail chiedono più spesso.",
   "Les vins aromatisés ne sont pas des spiritueux, mais on les utilise sans cesse au bar, et le plus important est le vermouth. Tous partent d'un vin, aromatisé avec des botaniques et porté à un degré plus élevé avec de l'alcool distillé. Ils sont en général sucrés et peuvent être colorés. C'est le vermouth que les cocktails demandent le plus souvent.",
   "Aromatised wines are not spirits, but they are used constantly behind the bar, and the most important is vermouth. All of them start as a wine, flavoured with botanicals and raised in strength with distilled alcohol. They are usually sweetened and may be coloured. Vermouth is the one cocktails call for most often."),
  v:()=>spF(fBottle(50,100,{col:WHITE,cork:1})+fT(50,152,w3("vino","vin","wine"),10)+[[spWormwood(0,20,.7),w3("botaniche","botaniques","botanicals")],[spBottle(0,0,"rgba(230,240,255,.5)",{s:.5}),w3("alcol","alcool","alcohol")],[spSugar(0,4,2),w3("zucchero","sucre","sugar")]].map(([g,l],i)=>fD(.6+i*.6,fT(92+i*58,104,"+",18,"#f3cd8a")+`<g transform="translate(${122+i*58} 96)">${g}</g>`+fT(122+i*58,152,l,9))).join("")
   +fD(2.6,fChip(160,30,w3("vino aromatizzato","vin aromatisé","aromatised wine"),"#8c1d40")+fChip(160,184,"vermouth = n°1 cocktail","#d4a23a","#2a1b20")))},
 {h:I3_("Il vino base","Le vin de base","The base wine"),
  c:I3_("Si pigiano le uve e il mosto fermenta subito. Si possono usare uve bianche o nere, ma quasi tutti scelgono una varietà bianca neutra e molto acida: dà un vino secco e discreto, su cui le botaniche risaltano. Sorpresa utile: la maggior parte dei vermouth rossi non nasce da vino rosso, ma da vino bianco colorato con caramello.",
   "On foule le raisin et le moût fermente aussitôt. On peut utiliser des raisins blancs ou noirs, mais presque tous choisissent une variété blanche neutre et très acide : elle donne un vin sec et discret, sur lequel les botaniques ressortent. Surprise utile : la plupart des vermouths rouges ne sont pas faits avec du vin rouge, mais avec du vin blanc coloré au caramel.",
   "Grapes are crushed and the juice fermented straight away. White or black grapes may be used, but nearly everyone chooses a neutral, high-acid white variety: it gives a dry, discreet wine against which the botanicals stand out. A useful surprise: most red vermouths are not made from red wine, but from white wine coloured with caramel."),
  v:()=>spF(fBunch(40,60,2.2,"#c8d77a")+fArrow("M70 90H92")+fTank(96,60,60,100,{col:WHITE,bub:5})+fChip(126,180,w3("bianco, neutro, acido","blanc, neutre, acide","neutral, high-acid"),"#5e8c31")
   +fD(1.6,fGlass(206,140,WHITE,1)+fT(232,110,"+",18,"#f3cd8a")+spMolasses(256,140)+fArrow("M276 124H290")+fGlass(300,140,"#8a2a1a",.8))
   +fD(2.6,fChip(254,40,w3("vermouth rosso","vermouth rouge","red vermouth"),"#8c1d40")+fChip(254,66,w3("= bianco + caramello","= blanc + caramel","= white + caramel"))))},
 {h:I3_("Tinture, distillati, ricette segrete","Teintures, distillats, recettes secrètes","Tinctures, distillates, secret recipes"),
  c:I3_("Le botaniche si lavorano di solito una per una, per macerazione, che dà tinture, o per ridistillazione, che dà distillati. Alcuni produttori invece le mettono a macerare direttamente nel vino. Non ci sono limiti agli aromi e la miscela esatta è un segreto ben custodito; sono ammessi anche alcuni aromi artificiali.",
   "Les botaniques sont en général traitées une à une, par macération, qui donne des teintures, ou par redistillation, qui donne des distillats. Certains producteurs les font plutôt macérer directement dans le vin. Il n'y a pas de limite aux arômes et le mélange exact est un secret bien gardé ; certains arômes artificiels sont aussi permis.",
   "Botanicals are usually processed one by one, by maceration, giving tinctures, or by redistillation, giving distillates. Some producers instead steep them directly in the wine. There is no limit on flavours and the exact blend is a closely guarded secret; certain artificial flavourings are allowed too."),
  v:()=>spF(fTank(20,70,70,90,{col:"#c98a3a"})+spBag(55,124)+fChip(55,180,w3("tinture","teintures","tinctures"),"#8a5a33")
   +fD(1,spPotStill(140,150,.5,{liq:"#e9e6d0"})+spBotDots(124,156,138,4)+fChip(160,180,w3("distillati","distillats","distillates"),"#3f7fa8"))
   +fD(2,fTank(240,70,60,90,{col:WHITE})+spBag(270,124)+fChip(270,180,w3("o nel vino","ou dans le vin","or in the wine"),"#5e8c31"))
   +fD(2.8,fChip(160,30,w3("ricetta segreta","recette secrète","secret recipe"),"#5c646b")))},
 {h:I3_("Fortificare: 14,5–22%","Fortifier : 14,5–22 %","Fortifying: 14.5–22%"),
  c:I3_("Si aggiunge alcol distillato, quasi sempre neutro, fino a portare il vino tra il 14,5% e il 22%. Questa fortificazione allunga la conservazione e rende il prodotto stabile; soprattutto impedisce al lievito di fermentare lo zucchero aggiunto, perché a quel grado non sopravvive. L'alcol neutro non porta sapori che farebbero concorrenza alle botaniche.",
   "On ajoute de l'alcool distillé, presque toujours neutre, pour amener le vin entre 14,5 % et 22 %. Ce mutage, ou fortification, allonge la conservation et rend le produit stable ; surtout, il empêche la levure de fermenter le sucre ajouté, car elle ne survit pas à ce degré. L'alcool neutre n'apporte pas de saveurs qui concurrenceraient les botaniques.",
   "Distilled alcohol, nearly always neutral, is added to bring the wine to between 14.5% and 22% abv. This fortification extends shelf life and keeps the product stable; above all, it stops yeast fermenting the added sugar, because yeast cannot survive at that strength. Neutral alcohol also brings no flavours to compete with the botanicals."),
  v:()=>spF(fTank(30,60,80,110,{col:WHITE})+spPour(150,40,80,74,"rgba(230,240,255,.9)",3)+spBottle(170,60,"rgba(230,240,255,.5)",{s:.55,rot:0})+fD(.8,spAbv(150,170,100,18,"14,5–22%","#d4a23a",.8,1))
   +fD(1.8,fYeast(230,80)+spNo(232,80,14)+fChip(250,110,w3("lievito fermo","levure stoppée","yeast stopped"),"#8c1d40"))
   +fD(2.6,fChip(250,150,w3("più stabile","plus stable","more stable"),"#5e8c31")+fChip(250,176,w3("alcol neutro","alcool neutre","neutral alcohol"),"#5c646b")))},
 {h:I3_("Assenzio maggiore: il segno del vermouth","L'absinthe : la marque du vermouth","Wormwood: the mark of vermouth"),
  c:I3_("Per la legge europea, ciò che rende un vino aromatizzato un vermouth è l'uso di piante della famiglia dell'assenzio nella ricetta. Il vermouth esiste in stile rosso o bianco e a diversi livelli di dolcezza, da secco a dolce. Questa doppia scelta, colore e zucchero, è ciò con cui gioca il barman scegliendo il vermouth per un cocktail.",
   "Selon la loi européenne, ce qui fait d'un vin aromatisé un vermouth, c'est l'emploi de plantes de la famille de l'absinthe dans la recette. Le vermouth existe en rouge ou en blanc et à plusieurs niveaux de douceur, du sec au doux. Ce double choix, couleur et sucre, est ce avec quoi joue le barman en choisissant un vermouth pour un cocktail.",
   "Under European law, what makes an aromatised wine a vermouth is the use of plants from the wormwood family in the recipe. Vermouth comes in red or white styles and at a range of sweetness levels, from dry to sweet. That double choice, colour and sugar, is what bartenders play with when picking a vermouth for a cocktail."),
  v:()=>spF(spWormwood(50,150,1.6)+fChip(54,176,w3("famiglia dell'assenzio","famille de l'absinthe","wormwood family"),"#5e8c31")
   +fD(1,spBottle(160,90,"#efe3a8",{lab:"DRY",s:.75})+spBottle(210,90,"#f2d68a",{lab:"BLANC",s:.75})+spBottle(260,90,"#7a1e14",{lab:"ROSSO",s:.75}))
   +fD(2,`<path d="M150 150H280" stroke="#e8dccf" stroke-width="2" marker-end="url(#fah)"/>`+fT(152,166,w3("secco","sec","dry"),9,"#f3cd8a","start")+fT(276,166,w3("dolce","doux","sweet"),9,"#f3cd8a","end")+fChip(214,190,w3("rosso o bianco","rouge ou blanc","red or white"),"#8c1d40")))},
 {h:I3_("Assemblare e far riposare","Assembler et laisser reposer","Blending and resting"),
  c:I3_("L'assemblaggio è l'ultima tappa: vino base secco, alcol distillato, distillati e tinture, zucchero e, se serve, caramello. Come in una ricetta dove ogni ingrediente è preparato a parte e va nella pentola solo alla fine. La miscela riposa di solito qualche settimana in acciaio per integrare i sapori; alcuni usano botti di rovere, che aggiungono complessità.",
   "L'assemblage est la dernière étape : vin de base sec, alcool distillé, distillats et teintures, sucre et, si besoin, caramel. Comme une recette où chaque ingrédient est préparé à part et ne va dans la casserole qu'à la fin. Le mélange repose en général quelques semaines en inox pour fondre les saveurs ; certains utilisent des fûts de chêne, qui ajoutent de la complexité.",
   "Blending is the final step: dry base wine, distilled alcohol, distillates and tinctures, sugar and, if needed, caramel. Think of a recipe where every ingredient is prepared separately and only goes into the pot at the end. The blend usually rests a few weeks in stainless steel so the flavours integrate; some producers use oak barrels, which add complexity."),
  v:()=>spF([[WHITE,w3("vino","vin","wine")],["rgba(230,240,255,.6)",w3("alcol","alcool","alcohol")],["#c98a3a",w3("tinture","teintures","tinctures")],["#e9e6d0",w3("distillati","distillats","distillates")],["#4a2410",w3("caramello","caramel","caramel")]].map(([c,l],i)=>fD(i*.3,spBottle(30+i*46,50,c,{s:.42})+fT(30+i*46,80,l,8,"#f3cd8a")+spPour(30+i*46,90,104,124,c,1.6))).join("")+fD(1.4,spSugar(240,60,2))
   +fD(1.8,spSteel(80,120,50,60)+fClock(150,150,w3("settimane","semaines","weeks")))+fD(2.6,fT(196,158,w3("o","ou","or"),11)+fBarrel(254,150,.6)+fChip(254,186,w3("più complessità","plus de complexité","more complexity"),"#5e8c31")))},
 {h:I3_("Ai piedi delle Alpi","Au pied des Alpes","Around the Alps"),
  c:I3_("I vini aromatizzati si possono fare ovunque e, con la moda dei cocktail, nascono nuove versioni in molti paesi. Eppure la grande maggioranza viene ancora da una zona a cavallo delle Alpi, tra il sud-est della Francia e il nord-ovest dell'Italia. E tra tutti i tipi il vermouth resta di gran lunga il più importante.",
   "Les vins aromatisés peuvent se faire partout et, avec la vogue des cocktails, de nouvelles versions apparaissent dans de nombreux pays. Pourtant, la grande majorité vient encore d'une zone à cheval sur les Alpes, entre le sud-est de la France et le nord-ouest de l'Italie. Et parmi tous les types, le vermouth reste de loin le plus important.",
   "Aromatised wines can be made anywhere, and with the cocktail boom new versions are appearing in many countries. Even so, the vast majority still comes from an area straddling the Alps, across south-east France and north-west Italy. Of all the types, vermouth remains by far the most important."),
  v:()=>spF(spAlps(40,150,240)+fD(.8,spPin(90,120,"#3f7fa8")+fChip(80,170,w3("Francia sud-est","sud-est de la France","SE France"),"#3f7fa8"))
   +fD(1.6,spPin(230,124,"#5e8c31")+fChip(240,170,w3("Italia nord-ovest","nord-ouest de l'Italie","NW Italy"),"#5e8c31"))
   +fD(2.4,fChip(160,30,w3("nuove versioni ovunque","nouveautés partout","new ones everywhere"),"#8c1d40")),"spring")}
]},
/* ===================== t1 Workstation, tools and glassware ===================== */
{id:"s2_bar", sec:"t", ch:"t1", ic:"bub", t:I3_("Il bar: postazione, attrezzi, bicchieri","Le bar : poste, matériel, verres","The bar: workstation, tools, glasses"), s:[
 {h:I3_("Bancone e retrobanco","Comptoir et arrière-bar","Counter and back bar"),
  c:I3_("Un bar è diviso in due metà, il bancone e il retrobanco, e il barman lavora nello spazio tra loro. Tutto è disposto perché i movimenti siano pochi e brevi: un bar ben organizzato serve più in fretta e meglio. Il bancone è diviso in postazioni individuali, diverse da locale a locale ma con elementi comuni.",
   "Un bar est divisé en deux moitiés, le comptoir et l'arrière-bar, et le barman travaille dans l'espace entre les deux. Tout est disposé pour que les gestes soient peu nombreux et courts : un bar bien organisé sert plus vite et mieux. Le comptoir est divisé en postes de travail individuels, différents selon les lieux mais avec des points communs.",
   "A bar is split into two halves, the bar counter and the back bar, and the bartender works in the space between them. Everything is arranged so that movements are few and short: a well-organised bar serves faster and better. The counter is divided into individual workstations, which vary between venues but share common features."),
  v:()=>spF(spBackBar(10,30,300)+fD(.6,spCounter(10,150,300))+fD(1.2,`<circle cx="160" cy="118" r="10" fill="#e8c9a8"/><path d="M146 150Q148 130 160 128Q172 130 174 150Z" fill="#2a1b20"/>`+`<path d="M110 136H134M210 136H186" stroke="#d4a23a" stroke-width="2" marker-end="url(#fah)"/>`)
   +fD(1.8,fChip(70,20,w3("retrobanco","arrière-bar","back bar"),"#8a5a33")+fChip(70,184,w3("bancone","comptoir","bar counter"),"#8a5a33")+fChip(250,184,w3("gesti brevi","gestes courts","short moves"),"#5e8c31")))},
 {h:I3_("Il piano di lavoro","Le plan de travail","The bar top"),
  c:I3_("La parte che vede il cliente è il piano del bancone, dove i drink si preparano su tappetini antigoccia che raccolgono gli schizzi prima che si spandano. A portata di mano ci sono porta tovaglioli, porta cannucce e gli attrezzi più usati: shaker, colini, jigger e cucchiai da bar.",
   "La partie que voit le client est le dessus du comptoir, où l'on prépare les boissons sur des tapis égouttoirs qui retiennent les éclaboussures avant qu'elles ne s'étalent. À portée de main se trouvent le distributeur de serviettes, le pot à pailles et les outils les plus utilisés : shaker, passoires, jiggers et cuillères à mélange.",
   "The part the customer sees is the bar top, where drinks are prepared on drip mats that catch spills before they spread. Within easy reach are a napkin holder, a straw caddy and the most-used tools: shakers, strainers, jiggers and bar spoons."),
  v:()=>spF(spCounter(0,140,320)+`<rect x="70" y="132" width="120" height="8" rx="2" fill="#2a2a2a"/>${Array.from({length:14},(_,i)=>`<circle cx="${76+i*8.4}" cy="136" r="1.6" fill="#4a4a4a"/>`).join("")}`+fChip(130,172,w3("tappetino antigoccia","tapis égouttoir","drip mat"),"#5c646b")
   +fD(.8,spShaker(96,126,.8)+spJigger(132,130,.8)+spSpoonBar(160,118,.8)+spHawthorne(176,124,.5))
   +fD(1.6,`<rect x="230" y="104" width="34" height="28" rx="3" fill="#fbf6ec"/><rect x="274" y="96" width="18" height="36" rx="3" fill="url(#spgl)" stroke="#e8dccf"/><path d="M278 96V74M283 96V70M288 96V76" stroke="#c4123a" stroke-width="2"/>`+fChip(262,60,w3("tovaglioli, cannucce","serviettes, pailles","napkins, straws"))))},
 {h:I3_("Il cuore della postazione","Le cœur du poste","The heart of the workstation"),
  c:I3_("Subito dietro c'è il cuore della postazione. Il pozzetto del ghiaccio, con cubetti e tritato, si usa solo con paletta o pinze, mai con le mani o un bicchiere. Il binario rapido tiene gli spiriti della casa; poi vaschette di guarnizioni, succhi freschi refrigerati, pistola della soda da tenere pulitissima, tagliere, cestino e lavello. Negli USA servono lavelli separati per attrezzi e mani.",
   "Juste derrière, le cœur du poste. Le bac à glace, glaçons et glace pilée, se sert à la pelle ou à la pince, jamais à la main ni avec un verre. Le speed rail garde les alcools de la maison ; puis bacs à garnitures, jus frais réfrigérés, pistolet à soda à garder très propre, planche, poubelle et évier. Aux États-Unis, outils et mains ont des éviers séparés.",
   "Directly behind sits the heart of the workstation. The ice well, with cubed and crushed ice, is served only with a scoop or tongs, never hands or a glass. The speed rail holds the house spirits; then garnish trays, chilled fresh juices, a soda gun kept spotless, a chopping board, a bin and a sink. In the USA separate sinks are required for tools and hands."),
  v:()=>spF(spIceWell(20,70,130)+fChip(85,56,w3("pozzetto del ghiaccio","bac à glace","ice well"),"#3f7fa8")+fD(.8,spScoop(186,84,.9)+spTongs(236,98,.8))
   +fD(1.4,spSpeedRail(20,160,7)+fChip(80,186,w3("binario rapido","speed rail","speed rail"),"#8c1d40"))
   +fD(2.2,`<rect x="180" y="134" width="40" height="22" rx="3" fill="#7a5a3c"/>`+spCitrus(192,140,6,LIME)+spCitrus(208,144,6,LEMON)+`<rect x="236" y="130" width="60" height="26" rx="4" fill="url(#fst)" stroke="#5c646b"/>`+fT(266,148,w3("lavello","évier","sink"),8.5,"#2a1b20")+fChip(250,186,w3("USA: 2 lavelli","USA : 2 éviers","USA: 2 sinks"),"#5c646b")))},
 {h:I3_("Retrobanco e conservazione","Arrière-bar et conservation","Back bar and storage"),
  c:I3_("Il retrobanco è magazzino e vetrina: sul piano e sugli scaffali spiriti, liquori e amari ispirano i clienti; sotto, frigoriferi e ripiani per vino, birra, bibite e bicchieri. Gli spiriti chiusi stanno al fresco, a temperatura costante e lontano dal sole. Una volta aperti l'ossigeno li degrada lentamente, più in fretta oltre la metà, e prima ancora i liquori a basso grado.",
   "L'arrière-bar est à la fois réserve et vitrine : sur le plan et les étagères, spiritueux, liqueurs et amers inspirent les clients ; dessous, réfrigérateurs et rayonnages pour vin, bière, sodas et verres. Fermés, les spiritueux se gardent au frais, à température constante, loin du soleil. Ouverts, l'oxygène les dégrade lentement, plus vite passé la moitié, et encore plus tôt les liqueurs peu alcoolisées.",
   "The back bar is both storage and shop window: on its counter and shelves, spirits, liqueurs and bitters inspire customers; below, fridges and shelving hold wine, beer, soft drinks and glassware. Unopened spirits are kept cool, at a constant temperature and out of sunlight. Once opened, oxygen slowly degrades them, faster past half empty, and sooner still for lower-strength liqueurs."),
  v:()=>spF(spBackBar(20,20,180)+fChip(110,104,w3("vetrina","vitrine","shop window"),"#d4a23a","#2a1b20")+fD(.8,`<rect x="20" y="118" width="180" height="56" rx="4" fill="#5c646b"/><rect x="26" y="124" width="80" height="44" rx="3" fill="#9fd3f0" opacity=".35"/><rect x="114" y="124" width="80" height="44" rx="3" fill="#9fd3f0" opacity=".35"/>`+fT(110,190,w3("frigo e scaffali","frigos et rayons","fridges, shelves"),9))
   +fD(1.8,fThermo(232,40,"",.3,"#3f7fa8")+fSun(286,46,8)+spNo(286,46,14))+fD(2.6,fChip(262,130,w3("aperto: ossigeno","ouvert : oxygène","opened: oxygen"),"#8c1d40")+fChip(262,156,w3("½ vuoto: più veloce","½ vide : plus vite","half empty: faster"))))},
 {h:I3_("Misurare con precisione","Mesurer avec précision","Measuring accurately"),
  c:I3_("Il jigger è un misurino calibrato: versa quantità precise ed è il modo più semplice per avere cocktail costanti ed equilibrati. Il beccuccio dosatore, montato sulle bottiglie più usate, limita il flusso e facilita il versamento nel jigger. Il cucchiaio da bar ha due compiti: misurare piccole quantità e mescolare.",
   "Le jigger est une mesure calibrée : il verse des quantités exactes et c'est le moyen le plus simple d'obtenir des cocktails constants et équilibrés. Le bec verseur, fixé sur les bouteilles les plus utilisées, limite le débit et facilite le versement dans le jigger. La cuillère à mélange a deux rôles : mesurer de petites quantités et remuer.",
   "The jigger is a calibrated measure: it pours accurate amounts and is the easiest way to make cocktails consistent and balanced. A bottle pourer, fitted to frequently used bottles, limits the flow and makes pouring into the jigger easier. The bar spoon has two jobs: measuring small quantities and stirring."),
  v:()=>spF(spPourer(90,90,1.3)+`<g transform="rotate(-35 90 90)"></g>`+fD(.6,spPour(104,24,150,110,"#d9a441",2.4)+spJigger(156,150,1.3))+fChip(120,182,w3("beccuccio + jigger","bec + jigger","pourer + jigger"),"#d4a23a","#2a1b20")
   +fD(1.6,spSpoonBar(256,110,1.4)+fChip(256,30,w3("misurare e mescolare","mesurer et remuer","measure and stir")))+fD(2.4,fChip(256,182,w3("cocktail costanti","cocktails constants","consistent drinks"),"#5e8c31")))},
 {h:I3_("Shaker, mixing glass e colini","Shaker, verre à mélange et passoires","Shakers, mixing glasses, strainers"),
  c:I3_("Lo shaker esiste in molti stili: a due pezzi, con due «tin» d'acciaio o una metà in vetro, oppure a tre pezzi. Il mixing glass serve per i drink mescolati. Ogni attrezzo ha il suo colino: lo Hawthorne con lo shaker, e spostandolo si regola la velocità di versamento; il Julep con il mixing glass. Hawthorne più colino fine è il doppio filtraggio.",
   "Le shaker existe en plusieurs styles : deux pièces, avec deux « tins » en inox ou une moitié en verre, ou trois pièces. Le verre à mélange sert aux boissons remuées. Chacun a sa passoire : la Hawthorne avec le shaker, et en la déplaçant on règle la vitesse de versement ; la Julep avec le verre à mélange. Hawthorne plus passoire fine, c'est le double filtrage.",
   "Shakers come in many styles: two-piece, with two steel tins or one glass half, or three-piece. The mixing glass is for stirred drinks. Each has its own strainer: the Hawthorne goes with the shaker, and shifting its position controls the pouring speed; the Julep strainer goes with the mixing glass. Hawthorne plus fine sieve is double straining."),
  v:()=>spF(spShaker(50,110,1.2)+fChip(50,160,"shaker","#5c646b")+fD(.6,spHawthorne(50,186,.6))+fD(1,fArrow("M90 180H104")+fT(140,176,"Hawthorne",9,"#f3cd8a"))
   +fD(1.6,spStir(240,110,"#c98a3a")+fChip(240,140,w3("mixing glass","verre à mélange","mixing glass"),"#5c646b")+spJulepStr(222,170,.7)+fT(276,186,"Julep",9,"#f3cd8a"))
   +fD(2.6,spSieve(150,60,1)+fChip(150,30,w3("doppio filtraggio","double filtrage","double straining"),"#8c1d40")))},
 {h:I3_("Attrezzi per guarnire","Outils pour garnir","Garnish tools"),
  c:I3_("Per le guarnizioni servono un coltello affilato; un pelapatate per pezzi di scorza grandi; il rigalimoni per strisce sottili; una grattugia, ad esempio per la noce moscata; e un accendino per le guarnizioni flambé, utile anche per le candele.",
   "Pour les garnitures, il faut un couteau bien aiguisé ; un éplucheur pour les grands morceaux de zeste ; un canneleur pour les fines lanières ; une râpe, par exemple pour la noix de muscade ; et un briquet pour les garnitures flambées, utile aussi pour les bougies.",
   "Garnishes need a sharp knife; a peeler for larger pieces of citrus peel; a channel knife for narrow strips of peel; a grater, for example for nutmeg; and a lighter for flamed garnishes, which also comes in handy for lighting candles."),
  v:()=>spF([[spKnife(0,0,1.1),w3("coltello","couteau","knife")],[spPeeler(0,0,1.1),w3("pelapatate","éplucheur","peeler")],[spChannel(0,0,1.1),w3("rigalimoni","canneleur","channel knife")],[spGrater(0,0,1),w3("grattugia","râpe","grater")],[spLighter(0,0,1.2),w3("accendino","briquet","lighter")]].map(([g,l],i)=>fD(.3+i*.45,`<g transform="translate(${36+i*62} 100)">${g}</g>`+fChip(36+i*62,i%2?170:150,l))).join("")
   +fD(2.8,spPeel(160,40,LEMON)+fChip(240,30,w3("scorza larga o fine","zeste large ou fin","wide or narrow peel"),"#d4a23a","#2a1b20")))},
 {h:I3_("Pestello, spremiagrumi, ghiaccio, aperture","Pilon, presse-agrumes, glace, ouverture","Muddler, juicer, ice, openers"),
  c:I3_("Il pestello schiaccia lime o menta per liberare succo e oli aromatici. Lo spremiagrumi è indispensabile perché i succhi devono essere sempre freschi; un modello a leva spreme le mezze arance e limoni. La paletta riempie shaker e bicchieri, le pinze posano i singoli cubetti. Infine l'apribottiglie per bibite e birre e il cavatappi a leva per il vino.",
   "Le pilon écrase citron vert ou menthe pour libérer jus et huiles aromatiques. Le presse-agrumes est indispensable, car les jus doivent toujours être frais ; un modèle à levier presse les demi-agrumes. La pelle remplit shakers et verres, la pince place les glaçons un par un. Enfin, le décapsuleur pour les sodas et les bières et le limonadier pour le vin.",
   "The muddler crushes lime or mint to release juice and aromatic oils. The juicer is essential because juices should always be fresh; a hinged hand press squeezes citrus halves efficiently. The scoop fills shakers and glasses, and tongs place single cubes. Finally, a bar blade opens mixers and beers, and a waiter's friend corkscrew opens wine."),
  v:()=>spF(spMuddler(40,150,1,1)+spCocktail(40,170,"rocks","#cfe6a8",{s:.9,mint:1})+fChip(40,190,w3("pestello","pilon","muddler"))
   +fD(.8,spJuicer(120,100,1.1)+fDrops(120,104,130,LEMON,3)+fChip(120,150,w3("spremiagrumi","presse-agrumes","juicer"),"#d4a23a","#2a1b20"))
   +fD(1.6,spScoop(196,60,1)+spTongs(204,130,.9)+fChip(196,166,w3("paletta e pinze","pelle et pince","scoop and tongs"),"#3f7fa8"))
   +fD(2.4,spBarBlade(278,80,1)+spCorkscrew(278,140,1)+fChip(278,186,w3("aprire","ouvrir","openers"),"#5c646b")))},
 {h:I3_("Bicchieri: lisci e short drink","Verres : purs et short drinks","Glasses: neat and short drinks"),
  c:I3_("Il bicchiere cambia l'aspetto del drink. Per gli spiriti lisci: lo shot, un sorso solo; il ballon, bocca stretta e coppa larga, per gli spiriti invecchiati in rovere; il tumbler o Old Fashioned, liscio, on the rocks o per cocktail forti. Per gli short drink senza ghiaccio, straight up: la coppa Martini a V, la coupe, il bicchiere Margarita. Il flute serve per lo Champagne Cocktail.",
   "Le verre change l'aspect de la boisson. Purs : le shot, bu d'un trait ; le ballon, large panse et ouverture étroite, pour les spiritueux vieillis en chêne ; le tumbler ou Old Fashioned, pur, on the rocks ou pour des cocktails forts. Pour les short drinks sans glace, straight up : le verre Martini en V, la coupe, le verre Margarita. La flûte sert au Champagne Cocktail.",
   "The glass changes how a drink looks. For neat spirits: the shot, drunk in one go; the balloon, wide bowl and narrow opening, for oak-aged spirits; the tumbler or Old Fashioned glass, for neat, on the rocks or spirit-forward drinks. For short drinks served without ice, straight up: the V-shaped Martini glass, the coupe and the Margarita glass. The flute is for the Champagne Cocktail."),
  v:()=>spF([["shot",(x)=>spGlass(x,120,"shot","#d9a441")],["balloon",(x)=>spGlass(x,120,"balloon","#c98a3a")],["tumbler",(x)=>spCocktail(x,120,"rocks","#c98a3a",{ice:1})],["Martini",(x)=>spCocktail(x,120,"martini","#eef3f6",{olive:1})],["coupe",(x)=>spCocktail(x,120,"coupe","#e9dc8c")],["Margarita",(x)=>spGlass(x,120,"margarita","#e6ecb0",{salt:1})],["flute",(x)=>spCocktail(x,120,"flute","#f2e2a0")]].map(([n,f],i)=>fD(.2+i*.3,f(26+i*45)+fT(26+i*45,140,n,8.5,"#f3cd8a"))).join("")
   +fD(2.6,fChip(70,176,w3("lisci","purs","neat"),"#8a5a33")+fChip(220,176,"straight up","#3f7fa8")))},
 {h:I3_("Long drink e bicchieri speciali","Long drinks et verres spéciaux","Long drinks and special vessels"),
  c:I3_("Per i long drink, con mixer e molto ghiaccio, regna l'highball o Collins. Lo sling, alto e affusolato su un piccolo stelo, deve il nome al Singapore Sling; l'hurricane, a pera, accoglie drink tropicali come la Piña Colada. Poi la tazza da Mule, la coppa da julep, il bicchiere da toddy per i drink caldi come l'Irish coffee, e la tazza tiki per i cocktail al rum.",
   "Pour les long drinks, avec mixer et beaucoup de glace, règne le highball ou Collins. Le sling, haut et effilé sur un petit pied, doit son nom au Singapore Sling ; l'hurricane, en poire, accueille les boissons tropicales comme la Piña Colada. Puis la tasse à Mule, la timbale à julep, le verre à toddy pour les boissons chaudes comme l'Irish coffee, et la tasse tiki, pour le rhum.",
   "For long drinks, with a mixer and plenty of ice, the highball or Collins glass rules. The sling, tall and tapered on a short stem, is named after the Singapore Sling; the pear-shaped hurricane holds tropical drinks such as the Piña Colada. Then the Mule mug, the julep cup, the toddy glass for hot drinks like Irish coffee, and the tiki mug for rum cocktails."),
  v:()=>spF([["highball",(x)=>spCocktail(x,110,"highball","#e9dc8c",{ice:1,bub:1,gar:LIME})],["sling",(x)=>spGlass(x,110,"sling","#e2627a")],["hurricane",(x)=>spGlass(x,110,"hurricane","#f2e6c8")],["Mule",(x)=>spGlass(x-4,110,"mule")],["julep",(x)=>spGlass(x,110,"julep")],["toddy",(x)=>spGlass(x,110,"toddy","#3a1a10")],["tiki",(x)=>spGlass(x,110,"tiki")]].map(([n,f],i)=>fD(.2+i*.3,f(26+i*45)+fT(26+i*45,130,n,8.5,"#f3cd8a"))).join("")
   +fD(2.6,fChip(60,170,"long drinks","#3f7fa8")+fChip(160,170,"Piña Colada","#d4a23a","#2a1b20")+fChip(262,170,"Irish coffee","#8a5a33")))}
]},
/* ===================== t2 Ingredients and balance ===================== */
{id:"s2_ingredients", sec:"t", ch:"t2", ic:"bub", t:I3_("Ingredienti ed equilibrio","Ingrédients et équilibre","Ingredients and balance"), s:[
 {h:I3_("Il ghiaccio: raffreddare, poi diluire","La glace : refroidir, puis diluer","Ice: chill first, then dilute"),
  c:I3_("Il ghiaccio ha due compiti: prima di tutto raffreddare il drink, poi aiutare la diluizione. Per farlo bene deve essere freddissimo e asciutto. Se è vicino a 0 °C raffredda poco e si scioglie troppo in fretta, annacquando il drink. Alcuni bar investono molto nel loro ghiaccio, ma i due formati base sono cubetti e tritato.",
   "La glace a deux rôles : d'abord refroidir la boisson, ensuite aider à la dilution. Pour bien le faire, elle doit être très froide et sèche. Si elle est proche de 0 °C, elle refroidit mal et fond trop vite, ce qui noie la boisson. Certains bars investissent beaucoup dans leur glace, mais les deux formats de base sont les glaçons et la glace pilée.",
   "Ice has two jobs: first and foremost to chill the drink, and second to help with dilution. To do this well it must be very cold and dry. If it is close to 0 °C it chills poorly and melts too fast, watering the drink down. Some bars invest heavily in their ice, but the two basic formats are cubed and crushed."),
  v:()=>spF(spIce(60,70,2.6,10)+spIce(100,90,2.2,-8)+fThermo(150,40,"-18 °C",.15,"#3f7fa8")+fChip(90,130,w3("freddo e asciutto","froid et sec","cold and dry"),"#3f7fa8")
   +fD(1.4,`<g opacity=".7">${spIce(240,80,2.2,4)}</g>`+fDrops(240,96,130,"#9fd3f0",3)+fChip(240,40,"≈ 0 °C","#8c1d40")+fChip(240,150,w3("si scioglie troppo","fond trop vite","melts too fast"),"#8c1d40"))
   +fD(2.4,fChip(160,184,w3("1 freddo, 2 diluizione","1 refroidir, 2 diluer","1 chill, 2 dilute"),"#5e8c31")))},
 {h:I3_("Shakerare o mescolare","Secouer ou remuer","Shaking or stirring"),
  c:I3_("I cubetti servono a preparare sia i drink shakerati sia quelli mescolati. Shakerare con i cubetti raffredda in fretta e diluisce poco. Mescolare raffredda più lentamente e, rispetto allo shaker, la diluizione può essere maggiore. Il ghiaccio usato per preparare si butta sempre: nel bicchiere va ghiaccio nuovo.",
   "Les glaçons servent à préparer aussi bien les boissons secouées que remuées. Secouer avec des glaçons refroidit vite et dilue un peu. Remuer refroidit plus lentement et, par rapport au shaker, la dilution peut être plus grande. La glace de préparation est toujours jetée : dans le verre, on met de la glace neuve.",
   "Cubed ice is used to prepare both shaken and stirred drinks. Shaking with cubes chills quickly and dilutes slightly. Stirring chills more slowly and, compared with shaking, dilution can be greater. Ice used for preparation is always discarded: the glass gets fresh ice."),
  v:()=>spF(spShaker(70,100,1.3,1)+fChip(70,150,w3("veloce, poca acqua","vite, peu d'eau","fast, slight dilution"),"#3f7fa8")
   +fD(1.2,spStir(230,120,"#c98a3a")+fChip(230,150,w3("lento, più acqua","lent, plus d'eau","slower, more water"),"#d4a23a","#2a1b20"))
   +fD(2.4,spIce(140,180,.8,10)+spIce(154,184,.8,-20)+fArrow("M166 180H190")+`<path d="M196 168H222L218 194H200Z" fill="#5c646b"/>`+fT(120,176,w3("si butta","on jette","discard"),9,"#f3cd8a","end")))},
 {h:I3_("Bicchiere pieno o ghiaccio tritato","Verre plein ou glace pilée","A full glass, or crushed ice"),
  c:I3_("Nel bicchiere i cubetti servono a raffreddare, non a diluire. Per questo un gin tonic o un Cuba Libre va servito in un bicchiere pieno di ghiaccio: con pochi cubetti il rapporto ghiaccio-liquido è basso e il ghiaccio si scioglie invece di raffreddare. Il tritato, invece, deve raffreddare e diluire in fretta, e dà a Mojito e Caipirinha il loro aspetto.",
   "Dans le verre, les glaçons sont là pour refroidir, pas pour diluer. C'est pourquoi un gin tonic ou un Cuba Libre se sert dans un verre rempli de glace : avec peu de glaçons, le rapport glace-liquide est faible et la glace fond au lieu de refroidir. La glace pilée, elle, doit refroidir et diluer vite, et donne au Mojito et à la Caipirinha leur aspect.",
   "In the glass, cubes are there to chill, not to dilute. That is why a gin and tonic or Cuba Libre is served in a glass full of ice: with only a few cubes the ice-to-liquid ratio is low and the ice melts rather than chills. Crushed ice, on the other hand, is meant to chill and dilute fast, and gives the Mojito and Caipirinha their look."),
  v:()=>spF(spCocktail(50,150,"highball","#e9dc8c",{ice:1,bub:1,gar:LIME,s:1.4})+fChip(50,176,w3("pieno: raffredda","plein : refroidit","full: chills"),"#5e8c31")
   +fD(1,`<g transform="translate(140 150) scale(1.4)"><path d="M-11 -48H11V-2Q11 0 9 0H-9Q-11 0 -11 -2Z" fill="#e9dc8c" opacity=".88"/>${spIce(0,-40,.8,10)}<path d="M-12 -62H12V-2Q12 2 9 2H-9Q-12 2 -12 -2Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/></g>`+fChip(140,176,w3("pochi: si scioglie","peu : fond","few: melts"),"#8c1d40"))
   +fD(2,`<g transform="translate(250 150) scale(1.4)"><path d="M-11 -48H11V-2Q11 0 9 0H-9Q-11 0 -11 -2Z" fill="#cfe6a8"/>${Array.from({length:22},(_,i)=>`<circle cx="${-8+(i*5)%17}" cy="${-4-Math.floor(i/4)*8}" r="2.2" fill="#eef8fc"/>`).join("")}${fLeaf(-3,-50,.7,-20,"#4f9a3a")}<path d="M-12 -62H12V-2Q12 2 9 2H-9Q-12 2 -12 -2Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/></g>`+fChip(250,30,w3("ghiaccio tritato","glace pilée","crushed ice"),"#3f7fa8")+fChip(250,176,"Mojito · Caipirinha","#5e8c31")))},
 {h:I3_("Sciroppi semplici e aromatizzati","Sirops simples et aromatisés","Simple and flavoured syrups"),
  c:I3_("Lo sciroppo semplice è il dolcificante preferito: un ingrediente già pronto rende più facile la precisione, e molti bar se lo preparano. Uno sciroppo comune è 2 parti di zucchero per 1 di acqua: dà la stessa dolcezza di un 1:1 in meno volume, lasciando spazio a ingredienti di carattere. Gli sciroppi si possono aromatizzare, come l'orzata, con mandorla e acqua di rose o di fiori d'arancio.",
   "Le sirop simple est l'édulcorant préféré : tout prêt, il facilite la précision, et beaucoup de bars le font maison. Un sirop courant est 2 parts de sucre pour 1 d'eau : il donne la même douceur qu'un 1:1 dans moins de volume, laissant de la place à des ingrédients de caractère. Les sirops peuvent être aromatisés, comme l'orgeat, à l'amande et à l'eau de rose ou de fleur d'oranger.",
   "Simple syrup is the preferred sweetener: a ready-made ingredient makes accuracy easier, and many bars make their own. A common syrup is 2 parts sugar to 1 part water: it gives the same sweetness as a 1:1 syrup in less volume, leaving room for more characterful ingredients. Syrups can also be flavoured, as with orgeat, made with almond and rose or orange flower water."),
  v:()=>spF(spSugar(40,70,2)+fT(70,92,"×2",14,"#f3cd8a")+fT(98,92,"+",14,"#f3cd8a")+`<rect x="110" y="62" width="22" height="30" rx="3" fill="#9fd3f0" opacity=".7"/>`+fT(146,92,"×1",14,"#f3cd8a")+fD(.8,fArrow("M90 104V122")+spBottle(90,150,"#f6efd8",{s:.6,lab:"2:1"})+fChip(90,186,w3("meno volume","moins de volume","less volume"),"#5e8c31"))
   +fD(1.8,spBottle(240,100,"#efe6d2",{lab:"ORGEAT",s:.9})+spNut(196,150,1)+`<circle cx="284" cy="146" r="7" fill="#f0a3b8"/><circle cx="284" cy="146" r="3" fill="#e0708c"/>`+fChip(240,184,w3("mandorla + fiori","amande + fleurs","almond + flowers"),"#d4a23a","#2a1b20")))},
 {h:I3_("Succhi freschi e bitter","Jus frais et bitters","Fresh juice and bitters"),
  c:I3_("I migliori barman usano solo succo di agrumi appena spremuto: si ossida in fretta, va tenuto in fresco e si degrada comunque in poche ore, così si prepara a lotti durante la serata. Altri succhi, come il mirtillo rosso, di solito si comprano pronti. I bitter da cocktail sono un condimento, mai un ingrediente principale.",
   "Les meilleurs barmen n'utilisent que du jus d'agrumes fraîchement pressé : il s'oxyde vite, doit rester au frais et se dégrade quand même en quelques heures, d'où des préparations par lots au fil de la soirée. D'autres jus, comme la canneberge, s'achètent en général tout prêts. Les bitters à cocktail sont un assaisonnement, jamais un ingrédient principal.",
   "The best bartenders use only freshly squeezed citrus juice: it oxidises quickly, must be kept chilled and still deteriorates within hours, so it is prepared in batches through the evening. Other juices, such as cranberry, are usually bought ready-made. Cocktail bitters are a seasoning, never a main ingredient."),
  v:()=>spF(spJuicer(60,60,1)+fDrops(60,64,90,LIME,3)+`<rect x="40" y="92" width="40" height="50" rx="4" fill="url(#spgl)" stroke="#e8dccf"/><rect x="42" y="104" width="36" height="36" fill="#cfe08a"/>`+fClock(120,100,w3("poche ore","quelques heures","hours"))+fChip(80,170,w3("fresco, a lotti","frais, par lots","fresh, in batches"),"#5e8c31")
   +fD(1.4,spBottle(196,100,"#b5153a",{s:.6})+fChip(190,146,w3("mirtillo: pronto","canneberge : achetée","cranberry: bought"),"#8c1d40"))
   +fD(2.2,spBitters(272,110,1)+fChip(272,176,w3("condimento","assaisonnement","seasoning"),"#8a5a33")))},
 {h:I3_("Guarnizioni","Garnitures","Garnishes"),
  c:I3_("La guarnizione decora il drink e spesso aggiunge un aroma sottile che ne esalta o completa un altro. Le più comuni: spicchi di limone e lime, menta, olive e ciliegie al maraschino. Quelle fresche si tagliano in giornata e si buttano a fine serata; la menta va trattata con cura perché non appassisca o si ammacchi. Olive e ciliegie conservate vanno comunque riposte bene.",
   "La garniture décore la boisson et ajoute souvent un arôme subtil qui en souligne ou complète un autre. Les plus courantes : quartiers de citron et de citron vert, menthe, olives et cerises au marasquin. Les fraîches se coupent le jour même et se jettent le soir ; la menthe se manipule avec soin pour ne pas faner. Olives et cerises conservées doivent quand même être bien stockées.",
   "A garnish decorates the drink and often adds a subtle aroma that accentuates or complements one in it. Common ones are lemon and lime wedges, mint, olives and maraschino cherries. Fresh garnishes are cut on the day and thrown away at the end of the night; mint needs gentle handling so it does not wilt or bruise. Preserved olives and cherries still need proper storage."),
  v:()=>spF(spCitrus(40,60,14,LEMON)+spCitrus(80,66,12,LIME)+fLeaf(130,74,1.4,0,"#4f9a3a")+`<ellipse cx="180" cy="62" rx="9" ry="7" fill="#7a9a3a"/><ellipse cx="200" cy="66" rx="9" ry="7" fill="#7a9a3a"/>`+spCherry(240,70,1.1)
   +fD(1,fChip(160,110,w3("decora + aroma","décore + arôme","decorate + aroma"),"#d4a23a","#2a1b20"))
   +fD(1.8,spKnife(60,150,.8)+fChip(80,186,w3("tagliate in giornata","coupées du jour","cut on the day"),"#5e8c31"))+fD(2.6,fChip(240,186,w3("menta: con cura","menthe : avec soin","mint: handle gently"),"#3f7fa8")))},
 {h:I3_("Forte contro debole","Fort contre faible","Strong versus weak"),
  c:I3_("L'equilibrio si costruisce con due bilance. La prima mette il forte, cioè la parte alcolica, contro il debole: succhi, soda, acqua tonica. È il grande vantaggio di un cocktail: godersi i sapori di uno spirito senza tutto il suo alcol. Anche il ghiaccio fuso è debole: in un Martini l'acqua di fusione è il principale elemento debole.",
   "L'équilibre se construit avec deux balances. La première oppose le fort, la partie alcoolique, au faible : jus, eau gazeuse, tonic. C'est le grand avantage d'un cocktail : profiter des saveurs d'un spiritueux sans tout son alcool. La glace fondue est aussi du faible : dans un Martini, l'eau de fonte est le principal élément faible.",
   "Balance is built with two sets of scales. The first sets strong, the alcoholic part, against weak: juice, soda water, tonic. That is the great advantage of a cocktail: enjoying a spirit's flavours without all its alcohol. Melted ice is weak too: in a Martini, meltwater is the main weak element."),
  v:()=>spF(spScale(160,160,spBottle(-70,-58,"#d9a441",{s:.4}),`<g transform="translate(70 -44)">${spIce(-6,0,1,10)+spIce(6,-4,1,-10)}${fDrops(0,4,14,"#9fd3f0",2)}</g>`)+fT(90,186,w3("forte","fort","strong"),11,"#f3cd8a")+fT(230,186,w3("debole","faible","weak"),11,"#9fd3f0")
   +fD(2,fChip(250,30,w3("succo, soda, tonica","jus, soda, tonic","juice, soda, tonic"),"#3f7fa8")+fChip(70,30,w3("Martini: acqua fusa","Martini : eau de fonte","Martini: meltwater"),"#8c1d40")))},
 {h:I3_("Dolce contro acido o amaro","Sucré contre acide ou amer","Sweet versus sour or bitter"),
  c:I3_("La seconda bilancia mette il dolce, da zucchero, sciroppo o liquore, contro l'acido degli agrumi o l'amaro dei bitter. Il vermouth è speciale perché porta sia dolcezza sia amarezza. Un esempio pratico: se un drink è stucchevole, un po' di succo di limone aiuta; se l'alcol brucia troppo, serve più elemento debole.",
   "La seconde balance oppose le sucré, venu du sucre, d'un sirop ou d'une liqueur, à l'acide des agrumes ou à l'amer des bitters. Le vermouth est particulier, car il apporte à la fois douceur et amertume. Un exemple pratique : si une boisson est écœurante, un peu de jus de citron aide ; si l'alcool brûle trop, il faut plus d'élément faible.",
   "The second scale sets sweet, from sugar, syrup or liqueur, against sour from citrus or bitter from cocktail bitters. Vermouth is special because it brings both sweetness and bitterness. A practical example: if a drink tastes cloying, a little lemon juice helps; if the alcohol burns, it needs more of the weak element."),
  v:()=>spF(spScale(160,160,`<g transform="translate(-70 -46)">${spSugar(-4,6,2)}</g>`,`<g transform="translate(70 -46)">${spCitrus(-8,-4,8,LEMON)}${spBitters(10,6,0).replace('translate(10 6)','translate(10 6) scale(.5)')}</g>`)+fT(90,186,w3("dolce","sucré","sweet"),11,"#f3cd8a")+fT(230,186,w3("acido / amaro","acide / amer","sour / bitter"),11,"#9cc65a")
   +fD(2,fChip(160,30,w3("vermouth: entrambi","vermouth : les deux","vermouth: both"),"#8c1d40"))+fD(2.8,fChip(64,56,w3("stucchevole? limone","écœurant ? citron","cloying? lemon"),"#5e8c31")+fChip(256,56,w3("brucia? più debole","brûle ? plus faible","burns? more weak"),"#3f7fa8")))}
]},
/* ===================== t3 Cocktail families ===================== */
{id:"s2_cocktails", sec:"t", ch:"t3", ic:"bub", t:I3_("Famiglie di cocktail","Familles de cocktails","Cocktail families"), s:[
 {h:I3_("Un albero genealogico","Un arbre généalogique","A family tree"),
  c:I3_("Centinaia di cocktail classici sembrano un labirinto, ma non lo sono. Tutti nascono dai quattro punti dell'equilibrio: forte, debole, acido o amaro, dolce. Si prende una ricetta equilibrata, si cambia un ingrediente e nasce un drink nuovo: così si formano le famiglie, highball, sour, Collins, punch e spirit-forward, divise tra short e long drink. Le proporzioni variano da bar a bar.",
   "Des centaines de cocktails classiques semblent un labyrinthe, mais ce n'en est pas un. Tous naissent des quatre points de l'équilibre : fort, faible, acide ou amer, sucré. On prend une recette équilibrée, on change un ingrédient et une boisson nouvelle naît : ainsi se forment les familles, highball, sour, Collins, punch et spirit-forward, entre short et long drinks. Les proportions varient selon les bars.",
   "Hundreds of classic cocktails can look like a maze, but they are not. All are built from the four points of balance: strong, weak, sour or bitter, sweet. Take a balanced recipe, swap one ingredient, and a new drink is born: that is how families form, highball, sour, Collins, punch and spirit-forward, split between short and long drinks. Exact proportions vary from bar to bar."),
  v:()=>spF(fBox(120,14,80,26,w3("4 punti","4 points","4 points"),{fill:"rgba(140,29,64,.75)"})+`<path d="M160 40V58M50 58H270M50 58V70M105 58V70M160 58V70M215 58V70M270 58V70" stroke="#d4a23a" stroke-width="1.6" fill="none"/>`
   +[["Highball","#3f7fa8"],["Collins","#3f7fa8"],["Punch","#3f7fa8"],["Sour","#d4a23a"],["Spirit-fwd","#d4a23a"]].map(([n,c],i)=>fD(.4+i*.35,fBox(16+i*55,72,68,26,n,{fill:c,sz:8.4}))).join("")
   +fD(2.4,spCocktail(64,170,"highball","#e9dc8c",{ice:1,s:.9})+fChip(64,190,"long drinks","#3f7fa8")+spCocktail(244,170,"coupe","#e9dc8c",{s:.9})+fChip(244,190,"short drinks","#d4a23a","#2a1b20"))
   +fD(3,fChip(160,140,w3("cambia 1 ingrediente","change 1 ingrédient","swap 1 ingredient"),"#5e8c31")))},
 {h:I3_("L'highball: costruito nel bicchiere","Le highball : monté dans le verre","The highball: built in the glass"),
  c:I3_("L'highball è il più semplice dei drink miscelati: uno spirito, il forte, allungato con un mixer, succo o soda, il debole, servito lungo sul ghiaccio. Gin tonic, vodka tonic e whisky soda sono esempi ovvi. Il metodo è il build: si versa direttamente nel bicchiere già pieno di cubetti, fino a circa un centimetro dal bordo. Niente shaker, niente colino.",
   "Le highball est le plus simple des mélanges : un spiritueux, le fort, allongé d'un mixer, jus ou soda, le faible, servi long sur glace. Gin tonic, vodka tonic et whisky soda en sont des exemples évidents. La méthode est le build : on verse directement dans le verre déjà rempli de glaçons, jusqu'à environ un centimètre du bord. Ni shaker, ni passoire.",
   "The highball is the simplest mixed drink: a spirit, the strong part, lengthened with a mixer, juice or soda, the weak part, served long over ice. Gin and tonic, vodka and tonic and whisky and soda are obvious examples. The method is building: pour straight into a glass already full of cubes, to about one centimetre from the rim. No shaker, no strainer."),
  v:()=>spF(spCocktail(160,170,"highball","#e9dc8c",{ice:1,bub:1,gar:LIME,s:1.9})+fD(.6,spBottle(60,70,"rgba(230,240,255,.5)",{s:.55})+spPour(70,40,150,56,"#e9dc8c",2)+fChip(60,120,w3("forte","fort","strong"),"#d4a23a","#2a1b20"))
   +fD(1.2,spBottle(260,70,"#cfe6f0",{s:.55})+fChip(260,120,w3("debole: mixer","faible : mixer","weak: mixer"),"#3f7fa8"))
   +fD(2,`<path d="M190 52H206M190 64H206" stroke="#f3cd8a" stroke-width="1.2"/>`+fT(212,62,"1 cm",9,"#f3cd8a","start")+fChip(160,22,"build","#8c1d40"))
   +fD(2.8,fChip(70,176,w3("bicchiere pieno","verre plein","glass full of ice"),"#5e8c31")))},
 {h:I3_("Highball con un nome","Des highballs qui ont un nom","Highballs with a name"),
  c:I3_("Alcuni highball hanno un nome proprio. Il Cuba Libre è rum e cola con lime. Il Moscow Mule è vodka allungata con ginger beer e lime, servito tradizionalmente nella tazza di rame. L'Horse's Neck unisce whisky, ginger ale e bitter: dimostra che anche un highball può avere un elemento amaro.",
   "Certains highballs ont leur propre nom. Le Cuba Libre, c'est rhum et cola avec citron vert. Le Moscow Mule, c'est vodka allongée de ginger beer et citron vert, servie traditionnellement dans la tasse en cuivre. Le Horse's Neck associe whisky, ginger ale et bitters : il montre qu'un highball peut aussi avoir un élément amer.",
   "Some highballs have a name of their own. The Cuba Libre is rum and cola with lime. The Moscow Mule is vodka topped with ginger beer and lime, traditionally served in a copper Mule mug. The Horse's Neck combines whisky, ginger ale and bitters, showing that a highball can have a bitter element too."),
  v:()=>spF(spDrink(56,"Cuba Libre","highball","#4a2410",{ice:1,bub:1,gar:LIME},[w3("rum, cola","rhum, cola","rum, cola"),"lime"],.2)
   +fD(1,fChip(160,24,"Moscow Mule","#8c1d40")+spGlass(160,116,"mule")+[w3("vodka, ginger beer","vodka, ginger beer","vodka, ginger beer"),"lime"].map((t,i)=>fT(160,136+i*12.5,t,8.6,"#f3cd8a")).join(""))
   +spDrink(264,"Horse's Neck","highball","#d9a441",{ice:1,bub:1},[w3("whisky, ginger ale","whisky, ginger ale","whisky, ginger ale"),w3("+ bitter","+ bitters","+ bitters")],1.8))},
 {h:I3_("Il sour: shakerato e filtrato","Le sour : secoué et filtré","The sour: shaken and strained"),
  c:I3_("Il sour si basa sull'equilibrio forte, acido, dolce: uno spirito, succo fresco di limone o lime e un dolcificante come lo sciroppo. Si shakera sul ghiaccio: lo shaker mescola, raffredda e soprattutto incorpora aria, per una consistenza leggera. Shakerando il ghiaccio si rompe, quindi si filtra con lo Hawthorne e spesso un colino fine.",
   "Le sour repose sur l'équilibre fort, acide, sucré : un spiritueux, du jus frais de citron ou de citron vert et un édulcorant comme le sirop. On le secoue sur glace : le shaker mélange, refroidit et surtout incorpore de l'air, pour une texture légère. En secouant, la glace se brise : on filtre donc avec la Hawthorne et souvent une passoire fine.",
   "The sour rests on the strong, sour, sweet balance: a spirit, fresh lemon or lime juice and a sweetener such as simple syrup. It is shaken over ice: shaking mixes and chills, but above all adds air, for a light, airy texture. Shaking also breaks up the ice, so the drink is strained through a Hawthorne and often a fine sieve."),
  v:()=>spF([[spBottle(0,0,"#d9a441",{s:.5}),w3("forte","fort","strong")],[spCitrus(0,4,12,LEMON),w3("acido","acide","sour")],[spBottle(0,0,"#f6efd8",{s:.5}),w3("dolce","sucré","sweet")]].map(([g,l],i)=>fD(i*.3,`<g transform="translate(${36+i*50} 60)">${g}</g>`+fT(36+i*50,100,l,9,"#f3cd8a"))).join("")
   +fD(1.2,spShaker(200,90,1.3,1)+fChip(200,30,w3("aria, freddo","air, froid","air, chill"),"#3f7fa8"))
   +fD(2.2,spHawthorne(250,120,.6)+spSieve(266,140,.7)+spCocktail(266,190,"coupe","#efe6c0",{foam:1,s:.9})+fChip(110,150,w3("Hawthorne + colino","Hawthorne + passoire","Hawthorne + sieve"),"#8c1d40")+fChip(110,176,w3("via le schegge","plus d'éclats","no ice shards"),"#5c646b")))},
 {h:I3_("I sour classici","Les sours classiques","Classic sours"),
  c:I3_("I sour classici usano un dolcificante neutro. Whisky Sour: Bourbon o rye, limone, sciroppo, albume facoltativo. Pisco Sour: pisco, lime, sciroppo e un albume, qui indispensabile per una consistenza morbida e piena. Daiquiri: rum bianco, agrume fresco, sciroppo. Tommy's Margarita: Tequila, lime e sciroppo d'agave.",
   "Les sours classiques utilisent un édulcorant neutre. Whisky Sour : Bourbon ou rye, citron, sirop, blanc d'œuf facultatif. Pisco Sour : pisco, citron vert, sirop et un blanc d'œuf, ici indispensable pour une texture souple et ample. Daiquiri : rhum blanc, agrume frais, sirop. Tommy's Margarita : Tequila, citron vert et sirop d'agave.",
   "Classic sours use an unflavoured sweetener. Whisky Sour: Bourbon or rye, lemon juice, simple syrup, optional egg white. Pisco Sour: pisco, lime, syrup and an egg white, essential here for a smooth, mouthfilling texture. Daiquiri: white rum, fresh citrus juice, syrup. Tommy's Margarita: Tequila, lime juice and agave syrup."),
  v:()=>spF(spDrinkY(42,24,"Whisky Sour","rocks","#e3b25a",{ice:1,gar:LEMON},["Bourbon / rye",w3("limone, sciroppo","citron, sirop","lemon, syrup"),w3("(albume)","(blanc d'œuf)","(egg white)")],.2)
   +spDrinkY(122,48,"Pisco Sour","coupe","#efe6c0",{foam:1},["pisco",w3("lime, sciroppo","citron vert, sirop","lime, syrup"),w3("+ albume!","+ blanc d'œuf !","+ egg white!")],.9)
   +spDrinkY(202,24,"Daiquiri","coupe","#eef0d0",{gar:LIME},[w3("rum bianco","rhum blanc","white rum"),w3("agrume, sciroppo","agrume, sirop","citrus, syrup")],1.6)
   +spDrinkY(282,48,"Tommy's","rocks","#e8e6b0",{ice:1,gar:LIME},["Tequila","lime",w3("sciroppo d'agave","sirop d'agave","agave syrup")],2.3))},
 {h:I3_("Sour con triple sec","Sours au triple sec","Sours with triple sec"),
  c:I3_("I sour più complessi cambiano il dolcificante o l'acido. Sostituendo lo sciroppo con il triple sec, un liquore all'arancia che porta dolcezza e aroma, nascono nuovi classici. Sidecar: Cognac, limone, triple sec. Margarita: Tequila, lime, triple sec, spesso con bordo di sale. Il Cosmopolitan aggiunge al lime un secondo acido, il mirtillo rosso, su base vodka.",
   "Les sours plus complexes changent l'édulcorant ou l'acide. En remplaçant le sirop par du triple sec, une liqueur d'orange qui apporte douceur et arôme, de nouveaux classiques naissent. Sidecar : Cognac, citron, triple sec. Margarita : Tequila, citron vert, triple sec, souvent avec un bord de sel. Le Cosmopolitan ajoute au citron vert un second acide, la canneberge, sur base vodka.",
   "More complex sours swap the sweetener or the sour element. Replace the syrup with triple sec, an orange liqueur bringing both sweetness and orange aroma, and new classics appear. Sidecar: Cognac, lemon, triple sec. Margarita: Tequila, lime, triple sec, often with a salt rim. The Cosmopolitan adds a second sour element, cranberry juice, to lime on a vodka base."),
  v:()=>spF(spDrink(58,"Sidecar","coupe","#e3b25a",{},["Cognac",w3("limone","citron","lemon"),"triple sec"],.3)
   +fD(1,fChip(160,24,"Margarita","#8c1d40")+spGlass(160,116,"margarita","#e6ecb0",{salt:1})+["Tequila","lime","triple sec"].map((t,i)=>fT(160,136+i*12.5,t,8.6,"#f3cd8a")).join(""))
   +spDrink(262,"Cosmopolitan","martini","#e2627a",{},["vodka","lime + "+w3("mirtillo","canneberge","cranberry"),"triple sec"],1.7)
   +fD(2.6,spPeel(76,186,ORANGE)+fT(170,190,w3("triple sec = arancia","triple sec = orange","triple sec = orange"),9,"#f39a2b")))},
 {h:I3_("La famiglia Collins","La famille Collins","The Collins family"),
  c:I3_("Il Collins è un sour diventato long drink: spirito, succo di limone o lime e dolcificante, allungati con soda su cubetti. Si shakerano i primi tre e si aggiunge la soda, oppure si costruisce tutto nel bicchiere. Tom Collins è con gin; cambiando lo spirito si hanno Vodka Collins, Pierre Collins con Cognac, Pedro Collins con rum.",
   "Le Collins est un sour devenu long drink : spiritueux, jus de citron ou de citron vert et édulcorant, allongés d'eau gazeuse sur glaçons. On secoue les trois premiers puis on ajoute la soda, ou bien on monte tout dans le verre. Le Tom Collins est au gin ; en changeant d'alcool, on obtient Vodka Collins, Pierre Collins au Cognac, Pedro Collins au rhum.",
   "The Collins is a sour turned into a long drink: spirit, lemon or lime juice and sweetener, topped with soda water over cubed ice. Either shake the first three and top with soda, or build everything in the glass. The Tom Collins uses gin; switch the spirit and you get the Vodka Collins, the Pierre Collins with Cognac and the Pedro Collins with rum."),
  v:()=>spF(spCocktail(70,150,"highball","#f2efd0",{ice:1,bub:1,gar:LEMON,s:1.5})+fChip(70,24,"Tom Collins","#8c1d40")+fT(70,170,w3("gin, limone, sciroppo","gin, citron, sirop","gin, lemon, syrup"),8.6,"#f3cd8a")+fT(70,184,"+ soda",9,"#9fd3f0")
   +[["Vodka","vodka"],["Pierre","Cognac"],["Pedro",w3("rum","rhum","rum")]].map(([n,sp],i)=>fD(1+i*.6,fChip(220,56+i*40,n+" Collins",["#5c646b","#d4a23a","#8a5a33"][i],i===1?"#2a1b20":undefined)+fT(220,74+i*40,sp,9,"#f3cd8a"))).join("")
   +fD(2.8,fArrow("M118 96H150")+fChip(220,186,w3("cambia lo spirito","change l'alcool","swap the spirit"),"#5e8c31")))},
 {h:I3_("Mojito, Paloma e punch","Mojito, Paloma et punch","Mojito, Paloma and punch"),
  c:I3_("Altri membri aggiungono ingredienti. Mojito: rum, lime, zucchero, foglie di menta pestate con delicatezza e soda, su ghiaccio tritato. Paloma: Tequila, lime e soda al pompelmo, oppure succo di pompelmo e soda. Il punch ha base sour ma usa succhi, spesso tropicali, con bitter o spezie; oggi è legato al rum e si serve anche in grandi ciotole da cui gli ospiti attingono col mestolo.",
   "D'autres membres ajoutent des ingrédients. Mojito : rhum, citron vert, sucre, feuilles de menthe pilées avec douceur et eau gazeuse, sur glace pilée. Paloma : Tequila, citron vert et soda au pamplemousse, ou jus de pamplemousse et eau gazeuse. Le punch a une base sour mais utilise des jus, souvent tropicaux, avec bitters ou épices ; lié au rhum, il se sert aussi en grands bols, à la louche.",
   "Other members add ingredients. Mojito: rum, lime, sugar, mint leaves muddled gently, and soda, over crushed ice. Paloma: Tequila, lime and grapefruit soda, or grapefruit juice plus soda water. Punch has a sour base but uses juices, often tropical, plus bitters or spices; today it is linked to rum and can be served in large bowls from which guests help themselves with a ladle."),
  v:()=>spF(spDrink(50,"Mojito","highball","#cfe6a8",{mint:1,gar:LIME},[w3("rum, lime, zucchero","rhum, citron vert","rum, lime, sugar"),w3("menta, soda","menthe, soda","mint, soda"),w3("ghiaccio tritato","glace pilée","crushed ice")],.2)
   +spDrink(150,"Paloma","highball","#f6c6b0",{ice:1,bub:1,gar:GRAPEF},["Tequila, lime",w3("soda pompelmo","soda pamplemousse","grapefruit soda")],1)
   +fD(1.8,fChip(256,24,"Punch","#8c1d40")+`<path d="M216 92Q256 132 296 92Z" fill="#e8843a" stroke="#e8dccf" stroke-width="1.4"/><path d="M228 96H284" stroke="#f3cd8a"/><path d="M286 60L262 98" stroke="#c9ced3" stroke-width="2.4"/><ellipse cx="262" cy="98" rx="6" ry="3" fill="#c9ced3"/>`+spPineapple(232,74,.6)+[w3("succhi tropicali","jus tropicaux","tropical juices"),w3("bitter o spezie","bitters ou épices","bitters or spices"),w3("ciotola e mestolo","bol et louche","bowl and ladle")].map((t,i)=>fT(256,136+i*12.5,t,8.6,"#f3cd8a")).join("")))},
 {h:I3_("Spirit-forward: mescolati","Spirit-forward : remués","Spirit-forward: stirred"),
  c:I3_("Gli spirit-forward sono più alcolici e celebrano il loro ingrediente forte; dolce e amaro si bilanciano con zucchero, vermouth e bitter. Si mescolano sul ghiaccio nel mixing glass, si filtrano con il Julep e si servono straight up o su cubetti. Mescolare è cruciale: controlla la diluizione. Manhattan e Martini usano vermouth; Old Fashioned e Sazerac zucchero e bitter. Il Negroni: gin, vermouth rosso, bitter da aperitivo in parti uguali.",
   "Les spirit-forward, plus alcoolisés, célèbrent leur ingrédient fort ; sucre, vermouth et bitters équilibrent sucré et amer. Remués sur glace au verre à mélange, filtrés à la Julep, servis straight up ou sur glaçons. Remuer règle la dilution. Manhattan et Martini : vermouth ; Old Fashioned et Sazerac : sucre et bitters. Negroni : gin, vermouth rouge, amer apéritif à parts égales.",
   "Spirit-forward cocktails are higher in alcohol and celebrate their strong ingredient; sweet and bitter are balanced with sugar, vermouth and bitters. They are stirred over ice in a mixing glass, strained with a Julep strainer and served straight up or on cubes. Stirring controls dilution. Manhattan and Martini use vermouth; Old Fashioned and Sazerac use sugar and bitters. Negroni: equal gin, red vermouth and aperitif bitter."),
  v:()=>spF(spStir(40,110,"#b8682a")+spJulepStr(40,140,.6)+fChip(40,184,w3("mescola, Julep","remuer, Julep","stir, Julep"),"#5c646b")
   +spDrinkY(116,24,"Manhattan","coupe","#8a3a1a",{},["rye","vermouth","bitters"],.8)+spDrinkY(186,48,"Old Fashioned","rocks","#c98a3a",{ice:1,gar:ORANGE},["whisky",w3("zucchero","sucre","sugar"),"bitters"],1.4)
   +spDrinkY(266,24,"Negroni","rocks","#b5153a",{ice:1,gar:ORANGE},["gin","vermouth","bitter"],2))},
 {h:I3_("Varianti di Martini e Manhattan","Variantes du Martini et du Manhattan","Martini and Manhattan variations"),
  c:I3_("Meno vermouth rende il Martini più «dry», più vermouth più «wet»; un po' di salamoia d'olive lo rende «dirty». La guarnizione, scorza di limone o pompelmo oppure oliva, conta più che in quasi ogni altro drink. Il Manhattan classico è rye, vermouth dolce e bitter: Sweet con sciroppo di maraschino, Dry con vermouth secco, Perfect con metà e metà. Con whiskey irlandese diventa Emerald, con Scotch Rob Roy.",
   "Moins de vermouth rend le Martini plus « dry », plus de vermouth plus « wet » ; un peu de saumure d'olive le rend « dirty ». La garniture, zeste ou olive, compte plus que presque partout ailleurs. Manhattan classique : rye, vermouth doux, bitters. Sweet avec sirop de marasquin, Dry avec vermouth sec, Perfect moitié-moitié. Au whiskey irlandais, c'est un Emerald ; au Scotch, un Rob Roy.",
   "Less vermouth makes a Martini 'drier', more makes it 'wetter', and a little olive brine makes it 'dirty'. The garnish, a lemon or grapefruit twist or an olive, matters more than in almost any other drink. The classic Manhattan is rye, sweet vermouth and bitters: Sweet with maraschino syrup, Dry with dry vermouth, Perfect with both. With Irish whiskey it becomes an Emerald; with Scotch, a Rob Roy."),
  v:()=>spF([["dry","#eef3f6",w3("meno vermouth","moins de vermouth","less vermouth")],["wet","#efe6c0",w3("più vermouth","plus de vermouth","more vermouth")],["dirty","#d8d6b0",w3("+ salamoia","+ saumure","+ olive brine")]].map(([n,c,l],i)=>fD(i*.4,spCocktail(34+i*52,82,"martini",c,{olive:i===2,gar:i===0?LEMON:undefined,s:.9})+fChip(34+i*52,104,n,"#5c646b")+fT(34+i*52,i%2?138:124,l,8,"#f3cd8a"))).join("")
   +fD(1.6,fChip(240,24,"Manhattan","#8c1d40")+[["Sweet",w3("+ maraschino","+ marasquin","+ maraschino")],["Dry",w3("vermouth secco","vermouth sec","dry vermouth")],["Perfect",w3("secco + dolce","sec + doux","dry + sweet")],["Emerald",w3("whiskey irlandese","whiskey irlandais","Irish whiskey")],["Rob Roy","Scotch"]].map(([n,l],i)=>fT(196,54+i*26,n,10,"#f3cd8a","start")+fT(252,54+i*26,l,8.6,"#fff4dc","start")).join(""))
   +fD(2.6,fChip(80,160,w3("guarnizione: conta","garniture : compte","garnish matters"),"#5e8c31")+spPeel(46,186,GRAPEF)+spPeel(110,186,LEMON)))}
]},
]);
